function statusBadge(s){const k=String(s||'ACTIVO').toLowerCase().replaceAll(' ','-');return `<span class="state state-${k}">${esc(s||'ACTIVO')}</span>`}
function controlSummary(e,type,label){const c=e.currentControl?.[type]||{};return `<div class="control-mini"><b>${label}</b><span>${esc(c.result||'SIN REGISTRO')}</span><small>Última: ${dateTxt(c.lastDate)} · Próxima: ${dateTxt(c.nextDate)}</small></div>`}
function externalCalibrationPointSummaries(e){const pts=e.plans?.calibration?.external?.points||[],map=e.currentControl?.calibrationExternalPoints||{};if(!pts.length)return'';return pts.map(pt=>{const scope=`EXT_POINT:${pt.id||normalizeKey(pt.label||pt.setpoint||'punto')}`,c=map[scope]||{},label=pt.label||`${pt.setpoint||''} ${pt.unit||''}`.trim();return `<div class="control-mini"><b>Calibración externa · ${esc(label)}</b><span>${esc(c.result||'SIN REGISTRO')}</span><small>Última: ${dateTxt(c.lastDate)} · Próxima: ${dateTxt(c.nextDate)}${c.certificateNumber?` · ${esc(c.certificateNumber)}`:''}</small></div>`}).join('')}
function maintenanceControlState(e,modality){
 const generic=e.currentControl?.maintenance||{};
 const specific=e.currentControl?.[modality==='INTERNAL'?'maintenanceInternal':'maintenanceExternal']||{};
 const genericMatches=modality==='INTERNAL'?generic.source==='MANTENIMIENTO_INTERNO':generic.source==='CONTROL_EXTERNO';
 const ev=typeof evidenceForProgram==='function'?evidenceForProgram(e,'MAINTENANCE',modality):null;
 const program=typeof buildProgramItems==='function'?buildProgramItems().find(i=>i.equipment?.id===e.id&&i.type==='MAINTENANCE'&&i.modality===modality):null;
 return {
  ...(genericMatches?generic:{}),
  ...specific,
  lastDate:specific.lastDate||(genericMatches?generic.lastDate:'')||program?.lastDate||ev?.generatedData?.date||ev?.issueDate||'',
  nextDate:specific.nextDate||(genericMatches?generic.nextDate:'')||program?.dueDate||ev?.generatedData?.nextDate||ev?.expiryDate||'',
  result:specific.result||(genericMatches?generic.result:'')||ev?.generatedData?.result||'SIN REGISTRO'
 };
}
function maintenanceControlSummary(e){
 const p=e.plans?.maintenance||{}, hasInt=modalityConfigured(p.preventiveModality,'INTERNAL'), hasExt=modalityConfigured(p.preventiveModality,'EXTERNAL');
 if(!p.preventiveRequired)return `<div class="control-mini"><b>Mant.</b><span>NO APLICA</span><small>Sin mantenimiento preventivo configurado</small></div>`;
 const cards=[];
 if(hasInt){const c=maintenanceControlState(e,'INTERNAL');cards.push(`<div class="control-mini"><b>${hasExt?'Mant. Int.':'Mant.'}</b><span>${esc(c.result||'SIN REGISTRO')}</span><small>Última: ${dateTxt(c.lastDate)} · Próxima: ${dateTxt(c.nextDate)}</small></div>`)}
 if(hasExt){const c=maintenanceControlState(e,'EXTERNAL'),freq=Number(p.external?.frequencyMonths)||0;cards.push(`<div class="control-mini"><b>${hasInt?'Mant. Ext.':'Mant.'}</b><span>${esc(c.result||'SIN REGISTRO')}</span><small>Última: ${dateTxt(c.lastDate)} · Próxima: ${freq?dateTxt(c.nextDate):'NO APLICA'}${freq?'':' · Por condición/falla'}</small></div>`)}
 return cards.join('');
}
function filteredEquipment(){return equipment.filter(e=>{
 const hay=[e.code,e.name,e.location,e.responsible,e.technical?.brand,e.technical?.model,e.technical?.serialNumber].join(' ').toLowerCase();
 return (!filters.q||hay.includes(filters.q.toLowerCase()))&&(!filters.status||e.status===filters.status)&&(!filters.location||e.location===filters.location)&&e.activeRecord!==false;
})}

function masterStatusForEquipment(e){
 const docs=dossier.filter(d=>d.equipmentId===e.id&&d.category==='FICHA_MAESTRA');
 const latest=latestDoc(docs,'FICHA_MAESTRA');
 const ds=e.documentStatus||{};
 if(!latest&&!ds.latestSignedRevision)return `<div class="master-state pending"><b>Sin ficha firmada</b><small>Pendiente de firma P12</small></div>`;
 const rev=latest?.revision||ds.latestSignedRevision||'—';
 const pending=ds.signatureState==='PENDIENTE_NUEVA_FIRMA'||ds.workingState==='BORRADOR_PENDIENTE_FIRMA'||!!(ds.latestSignedSnapshotHash&&ds.currentSnapshotHash&&ds.latestSignedSnapshotHash!==ds.currentSnapshotHash);
 if(pending){
  const next=ds.workingRevision||ds.pendingRevision||String((parseInt(String(rev).replace(/\D/g,''),10)||0)+1).padStart(2,'0');
  const sections=(ds.pendingChangeSections||[]).filter(Boolean);
  return `<div class="master-state warning"><b>Rev. ${esc(rev)} · última firmada</b><small>📝 Rev. ${esc(next)} de trabajo · pendiente de firma P12${sections.length?` · ${esc(sections.join(', '))}`:''}</small></div>`;
 }
 return `<div class="master-state ok"><b>Rev. ${esc(rev)} · FIRMADA</b><small>Ficha documental vigente</small></div>`;
}
// V1.1.208: resumen maestro por modalidad basado en el mismo programa que publica el QR.
// No inventa ejecución: PROGRAMADA indica fecha planificada, no conformidad.
function masterModalities(e){
 const definitions=[['CALIBRATION','INTERNAL','Calibración interna'],['CALIBRATION','EXTERNAL','Calibración externa'],['VERIFICATION','INTERNAL','Verificación interna'],['VERIFICATION','EXTERNAL','Verificación externa'],['MAINTENANCE','INTERNAL','Mantenimiento interno'],['MAINTENANCE','EXTERNAL','Mantenimiento externo']];
 let items=[];try{items=buildProgramItems().filter(i=>i.equipment?.id===e.id)}catch(err){console.warn('No se pudo resolver programa del equipo',e.code,err)}
 return definitions.map(([type,modality,label])=>{
  const records=items.filter(i=>i.type===type&&i.modality===modality);
  if(!records.length)return '';
  const rank={VENCIDA:0,HOY:1,SIN_FECHA:2,PROXIMA:3,PROGRAMADA:4,POR_CONDICION:5,VIGENTE:6};
  const governing=[...records].sort((a,b)=>(rank[a.status]??7)-(rank[b.status]??7))[0];
  return `<div class="control-mini" style="margin:4px 0"><b>${esc(label)}</b><span>${esc(governing.status||'SIN REGISTRO').replaceAll('_',' ')}</span>${records.map(i=>`<small>${i.methodName?esc(i.methodName)+' · ':''}Última: ${dateTxt(i.lastDate)} · Próxima: ${dateTxt(i.dueDate)} · ${i.frequency?esc(i.frequency)+' meses':i.conditionOnly?'Por condición':'Sin frecuencia'}</small>`).join('')}</div>`;
 }).filter(Boolean).join('')||'<div class="control-mini"><b>Control metrológico</b><span>Sin controles configurados</span></div>';
}
function renderInventory(){
 const rows=filteredEquipment(); const locations=[...new Set(equipment.map(e=>e.location).filter(Boolean))].sort();
 const counts={total:equipment.filter(e=>e.activeRecord!==false).length,activo:equipment.filter(e=>e.status==='ACTIVO'&&e.activeRecord!==false).length,restricted:equipment.filter(e=>['RESTRINGIDO','FUERA DE SERVICIO'].includes(e.status)&&e.activeRecord!==false).length,maint:equipment.filter(e=>e.status==='EN MANTENIMIENTO'&&e.activeRecord!==false).length};
 const content=`<section class="content inventory-page"><div class="module-title"><div><h1>Inventario Maestro</h1><p>Fuente maestra de identificación, características y planificación. Los resultados ejecutados serán alimentados por los módulos posteriores.</p></div><button class="btn btn-primary" id="newEquipment">＋ Nuevo equipo</button></div>
 <div class="kpis"><div class="kpi"><strong>${counts.total}</strong><span>Total registrados</span></div><div class="kpi"><strong>${counts.activo}</strong><span>Activos</span></div><div class="kpi"><strong>${counts.maint}</strong><span>En mantenimiento</span></div><div class="kpi"><strong>${counts.restricted}</strong><span>Restringidos / fuera de servicio</span></div></div>
 <div class="panel"><div class="inventory-toolbar"><input id="searchEq" class="control" placeholder="Buscar por código, equipo, marca, modelo, serie, ubicación..." value="${esc(filters.q)}"><select id="filterStatus" class="control"><option value="">Todos los estados</option>${['ACTIVO','EN MANTENIMIENTO','RESTRINGIDO','FUERA DE SERVICIO','BAJA'].map(x=>`<option ${filters.status===x?'selected':''}>${x}</option>`).join('')}</select><select id="filterLocation" class="control"><option value="">Todas las ubicaciones</option>${locations.map(x=>`<option ${filters.location===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div>
 <div class="table-wrap"><table class="equipment-table"><thead><tr><th>Código</th><th>Equipo</th><th>Ubicación</th><th>Estado</th><th>Ficha maestra</th><th>Control metrológico vigente</th><th>Responsable</th><th>Acciones</th></tr></thead><tbody>${rows.length?rows.map(e=>`<tr><td><b class="code">${esc(e.code)}</b></td><td><b>${esc(e.name)}</b><small>${esc([e.technical?.brand,e.technical?.model,e.technical?.serialNumber].filter(Boolean).join(' · '))}</small></td><td>${esc(e.location||'—')}</td><td>${statusBadge(e.status)}</td><td>${masterStatusForEquipment(e)}</td><td><div class="control-stack">${masterModalities(e)}</div></td><td>${esc(e.responsible||'—')}</td><td><div class="row-actions"><button class="icon-btn viewEq" data-id="${e.id}">Ver</button><button class="icon-btn editEq" data-id="${e.id}">Editar</button><button class="icon-btn statusEq" data-id="${e.id}">Estado</button><button class="icon-btn refreshQrEq" data-id="${e.id}" title="Publicar modalidades actuales en el QR">Actualizar QR</button></div></td></tr>`).join(''):`<tr><td colspan="8" class="empty-row">No existen equipos con los filtros seleccionados.</td></tr>`}</tbody></table></div></div>
 <div class="info-banner"><strong>Versión cargada: ${APP_VERSION}</strong> · <strong>Diseño dinámico:</strong> desde Inventario se define la <b>configuración</b>. Las fechas, resultados y documentos reales de calibraciones, verificaciones y mantenimientos aparecerán aquí automáticamente cuando construyamos sus módulos respectivos.</div></section>`;
 shell(content);
 document.querySelector('#newEquipment').onclick=()=>openEquipmentModal();
 searchEq.oninput=e=>{filters.q=e.target.value;renderInventory()}; filterStatus.onchange=e=>{filters.status=e.target.value;renderInventory()}; filterLocation.onchange=e=>{filters.location=e.target.value;renderInventory()};
 document.querySelectorAll('.editEq').forEach(b=>b.onclick=()=>openEquipmentModal(equipment.find(x=>x.id===b.dataset.id)));
 document.querySelectorAll('.viewEq').forEach(b=>b.onclick=()=>openEquipmentView(equipment.find(x=>x.id===b.dataset.id)));
 document.querySelectorAll('.statusEq').forEach(b=>b.onclick=()=>openStatusModal(equipment.find(x=>x.id===b.dataset.id)));
 document.querySelectorAll('.refreshQrEq').forEach(b=>b.onclick=async()=>{
  const e=equipment.find(x=>x.id===b.dataset.id);if(!e)return;
  b.disabled=true;b.textContent='Sincronizando…';
  try{await publishDerivedPublicEquipment(e);b.textContent='✓ Publicado';showGlobalToast(`Control Maestro de ${e.code} actualizado en QR.`,'ok')}
  catch(err){b.textContent='Reintentar QR';showGlobalToast(`No se pudo publicar ${e.code}: ${err?.message||err}`,'bad')}
  finally{b.disabled=false}
 });
}

function catalogOptions(key,current=''){
 const items=[...(catalogs[key]||[])];
 if(current && !items.includes(current)) items.unshift(current);
 return `<option value="">Seleccione</option>${items.map(x=>`<option value="${esc(x)}" ${x===current?'selected':''}>${esc(x)}</option>`).join('')}`;
}

function memoryField(id,label,key,value='',placeholder=''){
  const listId=`${id}_memory`;
  const options=(catalogState?.[key]||[]).map(v=>`<option value="${esc(v)}"></option>`).join('');
  return `<div class="field"><label>${label}</label><input class="control memory-input" id="${id}" list="${listId}" value="${esc(value||'')}" placeholder="${esc(placeholder)}" data-memory-key="${key}"><datalist id="${listId}">${options}</datalist></div>`;
}

function catalogField(id,label,key,current='',required=false){
 return `<div class="field"><label class="${required?'req':''}">${label}</label><div class="catalog-control"><select class="control" id="${id}">${catalogOptions(key,current)}</select><button class="catalog-add" type="button" data-catalog="${key}" data-target="${id}">＋ Agregar</button></div></div>`;
}
function smartOptions(key){return (catalogs[key]||[]).map(x=>`<option value="${esc(x)}"></option>`).join('')}
function smartField(id,label,key,current='',required=false,placeholder=''){
 const listId=`list_${id}`;
 return `<div class="field"><label class="${required?'req':''}">${label}</label><input class="control smart-memory" id="${id}" list="${listId}" data-memory-key="${key}" value="${esc(current)}" placeholder="${esc(placeholder)}" autocomplete="off"><datalist id="${listId}">${smartOptions(key)}</datalist><small class="memory-note">Puede escribir un valor nuevo. Se recordará automáticamente para futuros equipos.</small></div>`;
}
async function rememberSmartFields(){
 const jobs=[...document.querySelectorAll('.smart-memory')].map(el=>{const v=el.value.trim();return v?addCatalogItem(el.dataset.memoryKey,v,currentUser):Promise.resolve()});
 await Promise.allSettled(jobs);
}
async function handleCatalogAdd(button){
 const key=button.dataset.catalog,targetId=button.dataset.target;
 const labels={locations:'ubicación específica',responsibles:'responsable',operatingTemperatures:'temperatura de operación',operatingHumidities:'humedad de operación'};
 const value=prompt(`Ingrese el nuevo ${labels[key]||'valor'}:`)?.trim();
 if(!value)return;
 try{
   await addCatalogItem(key,value,currentUser);
   const select=document.querySelector('#'+targetId);
   if(select){
     if(![...select.options].some(o=>o.value===value))select.add(new Option(value,value));
     select.value=value;
   }
 }catch(err){alert('No se pudo agregar al catálogo: '+(err?.message||String(err)))}
}

