function techCustomRow(x={}){return `<tr class="tech-custom-row"><td><select class="control tc-cat">${['CARACTERÍSTICAS TÉCNICAS','CONTROL METROLÓGICO','CONDICIONES DE INSTALACIÓN Y OPERACIÓN','NORMATIVA / REFERENCIA','ACCESORIOS / SOFTWARE','OTROS'].map(v=>`<option ${x.category===v?'selected':''}>${v}</option>`).join('')}</select></td><td><input class="control tc-name" value="${esc(x.name||'')}" placeholder="Ej. Rango dinámico"></td><td><input class="control tc-value" value="${esc(x.value||'')}" placeholder="Información / requisito"></td><td><input class="control tc-unit" value="${esc(x.unit||'')}" placeholder="dB, °C..."></td><td><button type="button" class="icon-btn danger removeTechCustom">×</button></td></tr>`}
function suggestedTechTemplate(name=''){
 const k=normalizeKey(name);
 if(k.includes('minirae')||k.includes('mini rae')||k.includes('pgm-7320')||k.includes('pgm 7320')||k.includes('ei-203')||k.includes('ei/203'))return 'DETECTOR_COV_PID_MINIRAE3000';
 if(k.includes('medidor de cov')||k.includes('detector de cov')||k.includes('compuestos organicos volatiles')||k.includes('monitor de voc')||k.includes('detector pid')||k.includes('fotoionizacion'))return 'DETECTOR_COV_PID';
 if(k.includes('ei-201')||k.includes('ei/201')||k.includes('an100')||k.includes('an 100'))return 'ANEMOMETRO_EXTECH_AN100';
 if(k.includes('am4836c')||k.includes('am 4836c')||(k.includes('landtek')&&k.includes('anemometro')))return 'ANEMOMETRO_LANDTEK_AM4836C';
 if(k.includes('anemometro')||k.includes('anemómetro')||k.includes('am4836c')||k.includes('landtek')&&k.includes('velocidad del aire'))return 'ANEMOMETRO_GENERAL';
 if(k.includes('ei-199')||k.includes('ei/199')||k.includes('k-350')||k.includes('k350')||((k.includes('destilador')||k.includes('destilacion'))&&(k.includes('buchi')||k.includes('kjeldahl'))))return 'DESTILADOR_KJELDAHL_BUCHI_K350';
 if(k.includes('tetracal')||(k.includes('bgi')&&k.includes('flujo')))return 'MEDIDOR_FLUJO_TETRACAL';
 if(k.includes('medidor primario de flujo')||k.includes('calibrador de flujo')||k.includes('patron de flujo'))return 'MEDIDOR_FLUJO';
 if(k.includes('pq200')||k.includes('pq 200')||k.includes('bgi pq200')||k.includes('captador de material particulado')||k.includes('muestreador de material particulado')||k.includes('muestreador de particulas')||k.includes('muestreador de partículas')||k.includes('particulate sampler')||k.includes('air sampler')||k.includes('low volume sampler')||k.includes('pm10')||k.includes('pm2.5')||k.includes('pm2 5'))return 'CAPTADOR_MP';
 if(k.includes('ei-198')||k.includes('ei/198')||k.includes('ht30')||k.includes('bulbo humedo')||k.includes('bulbo húmedo')||k.includes('temperatura bh')||k.includes('temperatura bs')||k.includes('medidor digital de temperatura bh'))return 'MEDIDOR_TGBH';
 if(k.includes('termohigrom')||k.includes('termo higrom')||k.includes('thermohygrom')||k.includes('thermo hygrom')||k.includes('higrotermomet')||k.includes('higrometro digital'))return 'TERMOHIGROMETRO';
 if(k.includes('multiparametro')||k.includes('multi parametro')||k.includes('medidor de od')||k.includes('oxigeno disuelto')||k.includes('hq40d')||k.includes('hq 40d'))return 'MULTIPARAMETRO';
 if(k.includes('scrubber')||k.includes('b-414')||k.includes('b414')||k.includes('lavador de gases')||k.includes('lavado de gases')||k.includes('neutralizacion de vapores')||k.includes('neutralizador de vapores')||k.includes('sistema de neutralizacion'))return 'SCRUBBER';
 if(k.includes('termoreactor')||k.includes('termo reactor')||k.includes('drb200')||k.includes('drb 200')||k.includes('reactor digital')||k.includes('dry block reactor')||k.includes('bloque seco'))return 'TERMOREACTOR';
 if(k.includes('digestor')||k.includes('digestion unit')||k.includes('bloque digestion')||k.includes('bloque digestor')||k.includes('kjeldahl')||k.includes('k-425')||k.includes('k425'))return 'DIGESTOR';
 if(k.includes('cabina')&&(k.includes('flujo')||k.includes('laminar')||k.includes('bioseguridad')||k.includes('seguridad biolog')))return 'CABINA_FLUJO';
 if(k.includes('flujo laminar')||k.includes('laminar flow')||k.includes('biosafety cabinet'))return 'CABINA_FLUJO';
 if(k.includes('digestor')||k.includes('digestion unit')||k.includes('bloque digestor')||k.includes('kjeldahl')||k.includes('k-425')||k.includes('k425'))return 'DIGESTOR';
 if(k.includes('vibromet')||k.includes('vibracion')||k.includes('vibración')||k.includes('sv-106')||k.includes('sv106')||k.includes('ei-176'))return 'VIBROMETRO';
 if(k.includes('dosimet')||k.includes('dosimetria')||k.includes('dosimetría')||k.includes('sv-104')||k.includes('sv104'))return 'DOSIMETRO';
 if(k.includes('sonomet'))return 'SONOMETRO';
 if(k.includes('ei-189')||k.includes('abt 220-5dm')||(k.includes('kern')&&k.includes('balanza')))return 'BALANZA_EI189';
 if(k.includes('balanza')||k.includes('bascula'))return 'BALANZA';
 if(k.includes('phmetro')||k.includes('ph metro')||k.includes('medidor de ph'))return 'PHMETRO';
 if(k.includes('medidor de cloro')||k.includes('cloro residual')||k.includes('colorimetro portatil')||k.includes('pocket colorimeter')||k.includes('5870000')||k.includes('hach 8021')||k.includes('hach 8167'))return 'MEDIDOR_CLORO';
 if(k.includes('conduct'))return 'CONDUCTIMETRO';
 if(k.includes('espectrofot')||k.includes('uv visible'))return 'UVVISIBLE';
 return ''
}
