 document.querySelector('#suggestExternalCalPoints')?.addEventListener('click',()=>{const body=document.querySelector('#externalCalPointsBody');if(!body)return;const signal=[document.querySelector('#fName')?.value,document.querySelector('#tModel')?.value,document.querySelector('#tTemp')?.value,document.querySelector('#fUse')?.value].filter(Boolean).join(' ');const key=normalizeKey(signal);const existingPts=[...body.querySelectorAll('.ecp-setpoint')].map(x=>Number(x.value)).filter(Number.isFinite);let proposed=[];if(/termoreactor|drb\s*200|digestor|bloque|thermoreactor/.test(key))proposed=[105,150];else{const nums=[...signal.matchAll(/(?:^|[^0-9])(\d{2,3}(?:[.,]\d+)?)\s*°?\s*c/ig)].map(m=>Number(String(m[1]).replace(',','.'))).filter(x=>x>=-100&&x<=500);proposed=[...new Set(nums)].slice(0,4)}if(!proposed.length)proposed=[105,150];for(const sp of proposed){if(!existingPts.some(x=>Math.abs(x-sp)<0.001))body.insertAdjacentHTML('beforeend',externalCalibrationPointRow({label:`${sp} °C`,setpoint:sp,unit:'°C',frequencyMonths:document.querySelector('#cExtFreq')?.value||12,provider:document.querySelector('#cExtProv')?.value||''},existing))}bindExternalCalPoints();showGlobalToast(`IA propuso ${proposed.length} punto(s) de calibración externa. Conserve solo los que apliquen al equipo.`,'ok')});
