 const autoCorrection=(ev)=>{const r=ev.target.closest('.corr-row');if(!r||!ev.target.matches('.cr-ind,.cr-ref'))return;const num=x=>Number(String(x||'').replace(',','.'));const a=num(r.querySelector('.cr-ind')?.value),b=num(r.querySelector('.cr-ref')?.value);if(Number.isFinite(a)&&Number.isFinite(b)){r.querySelector('.cr-value').value=(b-a).toFixed(3).replace(/0+$/,'').replace(/\.$/,'')}};
