 const toggleVerificationStrategy=()=>{
   const s=document.querySelector('#vStrategy')?.value||'VARIABLE_USO';
   document.querySelector('#vFixedWrap')?.classList.toggle('hidden-by-rule',s!=='FIJO');
   document.querySelector('#vDefinedWrap')?.classList.toggle('hidden-by-rule',s!=='DEFINIDOS');
   document.querySelector('#vRuleWrap')?.classList.toggle('hidden-by-rule',!['DEFINIDOS','VARIABLE_USO','ALEATORIO_RANGO','ANALISTA'].includes(s));
   const count=document.querySelector('#vCount');
   if(count){
     if(s==='FIJO'){count.value='1';count.disabled=true;}
     else count.disabled=false;
   }
   const help=document.querySelector('#vStrategyHelp');
   const texts={
    FIJO:'El mismo punto se utiliza en cada verificación. Puede provenir de Metrología.',
    DEFINIDOS:'Se verifican puntos establecidos previamente. Puede registrar uno o varios.',
    VARIABLE_USO:'El punto se decide al ejecutar la verificación según el uso real del equipo. Recomendado para perillas o regulaciones variables.',
    ALEATORIO_RANGO:'El punto se selecciona dentro del rango de uso definido en Metrología. El módulo de Verificación podrá proponerlo automáticamente.',
    ANALISTA:'El analista define el punto al ejecutar la verificación y queda trazado quién lo seleccionó y el criterio usado.'
   };
   if(help) help.innerHTML=`<strong>${document.querySelector('#vStrategy')?.selectedOptions?.[0]?.textContent||''}</strong><span>${texts[s]||''}</span>`;
 };
