 document.querySelectorAll('.editExternalEvidence').forEach(b=>b.onclick=()=>{if(!requestExternalEditPassword())return;const i=all.find(x=>x.id===b.dataset.task),d=dossier.find(x=>x.id===b.dataset.doc);if(i&&d)openExternalControlModal(i,d)});
 document.querySelectorAll('.externalDossier').forEach(b=>b.onclick=()=>{currentPage='dossier';filters.dq=equipment.find(e=>e.id===b.dataset.eqid)?.code||'';renderApp()});
