 let m=t.match(/(20\d{2})[-\/]([a-z]{3,10}|\d{1,2})[-\/](\d{1,2})/i);
 const months={ene:1,enero:1,feb:2,febrero:2,mar:3,marzo:3,abr:4,abril:4,may:5,mayo:5,jun:6,junio:6,jul:7,julio:7,ago:8,agosto:8,sep:9,sept:9,septiembre:9,oct:10,octubre:10,nov:11,noviembre:11,dic:12,diciembre:12};
 if(m){const mm=/^\d+$/.test(m[2])?Number(m[2]):months[m[2].slice(0,3)]||months[m[2]];if(mm)return `${m[1]}-${String(mm).padStart(2,'0')}-${String(Number(m[3])).padStart(2,'0')}`}
 m=t.match(/(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)\s+(?:del\s+)?(20\d{2})/i);
