 const date=parseSpanishDateLoose((text.match(/FECHA DE (?:ELABORACI[ÓO]N|REALIZACI[ÓO]N)[\s\S]{0,80}/i)||[])[0]||'')||parseSpanishDateLoose(text);
 const nextDate=parseSpanishDateLoose((text.match(/FECHA PR[ÓO]XIMA[\s\S]{0,80}/i)||[])[0]||'');
