 const nums=(re)=>[...norm.matchAll(re)].map(m=>Number(m[1])).filter(Number.isFinite);
 const corr=nums(/x̄\s*CORR\.?\s*([0-9]+(?:\.[0-9]+)?)/gi).filter(v=>v>=0.1&&v<=1);
 const workFlow=corr.length?Math.min(...corr):((norm.match(/(?:nivel de trabajo|trabajo)[\s\S]{0,900}?promedio corregido[^0-9]*([0-9]+(?:\.[0-9]+)?)/i)||[])[1]?Number((norm.match(/(?:nivel de trabajo|trabajo)[\s\S]{0,900}?promedio corregido[^0-9]*([0-9]+(?:\.[0-9]+)?)/i)||[])[1]):null);
 const flowU=((norm.match(/INCERTIDUMBRE DE\s+MEDICI[ÓO]N\s*([0-9]+(?:\.[0-9]+)?)/i)||[])[1]);
 const hepaVals=[...norm.matchAll(/(?:M[1-9]|%\s*P[1-9])\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)%?/gi)].map(m=>Number(m[1])).filter(v=>Number.isFinite(v)&&v>=0&&v<1);
 const hepaMax=hepaVals.length?Math.max(...hepaVals):null;
