function laminarMetricRisk(m){
 if(m.value==null)return null;
 if(m.boolean)return m.value?0:1.2;
 if(m.lower!=null&&m.upper!=null){if(m.value<m.lower||m.value>m.upper)return 1.2;const span=m.upper-m.lower;const margin=Math.min(m.value-m.lower,m.upper-m.value);return Math.max(0,1-(margin/(span/2)));}
 if(m.upper!=null){if(m.value>m.upper)return 1.2;return Math.max(0,m.value/m.upper)}
 if(m.lower!=null){if(m.value<m.lower)return 1.2;return Math.max(0,m.lower/Math.max(m.value,1e-9))}
 return null;
}
function evaluateLaminarCabinetInterval(current,previous,currentInterval=12){
 const cur=Math.max(1,Number(currentInterval)||12),maxNormal=12;
 const rows=current.metrics.map(m=>{const p=previous?.metrics?.find(x=>x.key===m.key)||null;const risk=laminarMetricRisk(m),prevRisk=p?laminarMetricRisk(p):null;const worsening=(risk!=null&&prevRisk!=null)?risk-prevRisk:null;let status='SIN DATO';if(risk!=null){status=risk>1?'NO CONFORME':risk>=0.90?'VIGILANCIA':risk>=0.70?'ATENCIÓN':'ESTABLE'}return {...m,risk,previous:p,previousRisk:prevRisk,worsening,status}});
 const nonconforming=rows.some(r=>r.risk!=null&&r.risk>1)||current.approved===false;
 const worst=Math.max(0,...rows.map(r=>r.risk==null?0:r.risk));
 const trendWorse=Math.max(0,...rows.map(r=>r.worsening==null?0:r.worsening));
 let recommendation=Math.min(cur,maxNormal),overall='ESTABLE',reason='Desempeño conforme; se mantiene la recalificación anual como intervalo normal máximo para esta familia.';
 if(nonconforming){recommendation=Math.min(cur,3);overall='NO CONFORME';reason='Existe al menos un criterio fuera de especificación. Requiere intervención y recalificación extraordinaria antes de volver al régimen normal.'}
 else if(worst>=0.90&&trendWorse>=0.15){recommendation=Math.min(cur,6);overall='CRÍTICO';reason='El parámetro gobernante está muy próximo al límite y además empeoró respecto al ciclo anterior; se recomienda reducir el intervalo.'}
 else if(trendWorse>=0.15){recommendation=Math.min(cur,9);overall='VIGILANCIA';reason='Se detecta deterioro relevante frente al ciclo anterior; se recomienda acortar temporalmente el intervalo y revisar tendencia.'}
 else if(worst>=0.90){recommendation=Math.min(cur,12);overall='VIGILANCIA';reason='El equipo cumple, pero al menos una variable opera en o muy cerca de su límite. Se mantiene 12 meses y se recomienda verificación intermedia a 6 meses.'}
 recommendation=Math.max(1,Math.round(recommendation));
 return {family:'LAMINAR_CABINET',currentInterval:cur,maxInterval:maxNormal,recommendationMonths:recommendation,overall,reason,intermediateCheckMonths:overall==='ESTABLE'?6:Math.min(6,recommendation),evaluated:rows,usableCount:rows.filter(r=>r.risk!=null).length,previousReport:previous?.reportNumber||'',currentReport:current.reportNumber||'',annualValidity:!!current.annual};
}
