async function extractPdfCertificatePages(file){
 if(!file)throw new Error('Seleccione primero el certificado PDF.');
 if(!/pdf/i.test(file.type||'')&&!/\.pdf$/i.test(file.name||''))throw new Error('La lectura inteligente requiere un PDF con texto seleccionable.');
 const pdfjs=await import('pdfjs-dist/legacy/build/pdf.mjs');
 try{pdfjs.GlobalWorkerOptions.workerSrc=new URL('pdfjs-dist/build/pdf.worker.min.mjs',import.meta.url).toString()}catch{}
 const bytes=new Uint8Array(await file.arrayBuffer()); const pdf=await pdfjs.getDocument({data:bytes}).promise; const pages=[],itemPages=[];
 for(let n=1;n<=pdf.numPages;n++){
  const page=await pdf.getPage(n),tc=await page.getTextContent(),items=tc.items.map(x=>({s:String(x.str||'').trim(),x:Number(x.transform?.[4]||0),y:Number(x.transform?.[5]||0),w:Number(x.width||0),h:Number(x.height||0)})).filter(x=>x.s);
  const groups=[]; for(const it of items){let g=groups.find(z=>Math.abs(z.y-it.y)<=2.5);if(!g){g={y:it.y,items:[]};groups.push(g)}g.items.push(it)}
  groups.sort((a,b)=>b.y-a.y); groups.forEach(g=>g.items.sort((a,b)=>a.x-b.x));
  const lines=groups.map(g=>g.items.map(i=>i.s).join(' ').replace(/\s+/g,' ').trim()).filter(Boolean); pages.push(lines);itemPages.push(groups);
 }
 return {pages,itemPages,text:pages.flat().join('\n')};
}
function parseIsoDateNear(text,label){
 const i=String(text).toLowerCase().indexOf(String(label).toLowerCase()); if(i<0)return''; const seg=String(text).slice(i,i+220); const m=seg.match(/(20\d{2})[-\/]([01]?\d)[-\/]([0-3]?\d)/); return m?`${m[1]}-${String(m[2]).padStart(2,'0')}-${String(m[3]).padStart(2,'0')}`:'';
}
function parseSonometerCertificate(struct){
 const lines=struct?.pages?.flat?.()||String(struct?.text||'').split(/\n/); const text=lines.join('\n').replace(/−/g,'-');
 const cert=(text.match(/(?:N[°ºo]\s*)?(CGC-\d+-\d+-\d+)/i)||[])[1]||''; const date=parseIsoDateNear(text,'Fecha de Calibración')||parseIsoDateNear(text,'Calibration Date');
 const adjusted=/¿?Se realiza Ajuste\??[\s\S]{0,120}\bS[IÍ]\b/i.test(text)||/Is Adjustment Done\?[\s\S]{0,120}\bYES\b/i.test(text);
 let mode='',weight=''; const rows=[]; const n=v=>Number(String(v).replace(',','.'));
 const push=(section,w,point,emp,error,u)=>{if(![emp,error,u].every(Number.isFinite))return; const key=`${section}|${w}|${point}`.toLowerCase(); if(rows.some(r=>r.comparisonKey===key))return; rows.push({id:`pdf-${rows.length+1}`,comparisonKey:key,section,weight:w,magnitude:section==='REF'?'Nivel de presión sonora':section==='OCT'?'Respuesta en frecuencia':section==='TIME'?'Ponderación temporal':'Sonómetro',unit:section==='TIME'?'dB/s':'dB',point,emp,error,uncertainty:u});};
 for(let idx=0;idx<lines.length;idx++){
  const raw=String(lines[idx]).replace(/−/g,'-').replace(/,/g,'.').trim(); const low=raw.toLowerCase();
  if(/frecuencia de referencia|reference frequenc/.test(low))mode='REF';
  if(/respuesta de frecuencia a banda de octava|frequency response to octave band/.test(low))mode='OCT';
  if(/respuesta de ponderaci[oó]n temporal|time weighting response/.test(low))mode='TIME';
  if(/pruebas el[eé]ctricas|electrical tests/.test(low))mode='ELECTRICAL';
  if(/^ponderaci[oó]n a\b|^a-weighting\b/.test(low))weight='A';
  if(/^ponderaci[oó]n c\b|^c-weighting\b/.test(low))weight='C';
  if(mode==='TIME'){
   let m=raw.match(/^(Fast|Slow)\s+([+-]?\d+(?:\.\d+)?)\s+([+-]?\d+(?:\.\d+)?)\s+([+-]?\d+(?:\.\d+)?)\s+(.+?)\s+([+-]?\d+(?:\.\d+)?)\s+(?:Cumple|Compliance)/i);
   if(m){const lim=m[1].toLowerCase()==='fast'?3.7:0.7;push('TIME',m[1].toUpperCase(),m[1],lim,n(m[4]),n(m[6]));continue}
  }
  if(mode==='OCT'&&['A','C'].includes(weight)){
   let m=raw.match(/^(31\.5|63|125|250|500|1000|2000|4000|8000)\s+([+-]?\d+(?:\.\d+)?)\s+([+-]?\d+(?:\.\d+)?)\s+([+-]?\d+(?:\.\d+)?)\s+([+-]?\d+(?:\.\d+)?)\s+([+-]?\d+(?:\.\d+)?)\s+(?:Cumple|Compliance)/i);
   if(m){push('OCT',weight,`${m[1]} Hz`,n(m[5]),n(m[4]),n(m[6]));continue}
  }
  if(mode==='REF'&&['A','C'].includes(weight)){
   // Las filas de 94/104/114 dB pueden no repetir 1000 Hz en cada renglón.
   let m=raw.match(/^(94(?:\.0)?|104(?:\.0)?|114(?:\.0)?)\s+([+-]?\d+(?:\.\d+)?)\s+([+-]?\d+(?:\.\d+)?)\s+([+-]?\d+(?:\.\d+)?)\s+([+-]?\d+(?:\.\d+)?)\s+(?:Cumple|Compliance)/i);
   if(m){push('REF',weight,`1000 Hz · ${Number(m[1])} dB`,n(m[4]),n(m[3]),n(m[5]));continue}
  }
 }
 return {certificateNumber:cert,date,adjusted,rows};
}
