 const universalBanner=document.createElement('div');universalBanner.id='ecUniversalDecisionBanner';universalBanner.className='info-banner';universalBanner.innerHTML='<b>Criterio del certificado:</b> compare el error del certificado contra el error máximo permitido (EMP).';document.querySelector('#ecGenericAnalysisTableWrap')?.before(universalBanner);
