 const renderRowsIntoTable=(rows)=>{const th=isThermohygrometerEquipment(selected()?.equipment);if(th&&universalHead)universalHead.innerHTML='<th>Magnitud</th><th>Punto</th><th>Error máximo permitido</th><th>Error actual *</th><th class="hidden-by-rule">U</th><th class="hidden-by-rule">Corrección</th><th class="hidden-by-rule">Aplicación</th>';else if(universalHead)universalHead.innerHTML='<th>Magnitud</th><th>Punto</th><th>EMP</th><th>Error actual *</th><th>U expandida *</th><th>Corrección certificada</th><th>Confirmar aplicación</th>';document.querySelectorAll('.ec-correction-head').forEach(x=>x.classList.toggle('hidden-by-rule',th));ecAnalysisRows.innerHTML=rows.map(r=>`<tr data-id="${esc(r.id)}" data-key="${esc(r.comparisonKey||'')}" data-section="${esc(r.section||'')}" data-weight="${esc(r.weight||'')}" data-magnitude="${esc(r.magnitude)}" data-unit="${esc(r.unit)}"><td><b>${esc(r.magnitude)}</b><small>${esc([r.section,r.weight].filter(Boolean).join(' · ')||r.unit||'')}</small></td><td><input class="control eca-point" value="${esc(r.point||'')}">${th?'<button type="button" class="icon-btn th-remove" title="Quitar punto">×</button>':''}</td><td><input class="control eca-emp" value="${th?(r.unit==='°C'?1:5):(r.emp??'')}" ${th?'readonly':''} placeholder="EMP"></td><td><input class="control eca-error" type="number" step="any" value="${r.error??''}" placeholder="Error del certificado"></td><td class="${th?'hidden-by-rule':''}"><input class="control eca-u" type="number" min="0" step="any" value="${r.uncertainty??''}" placeholder="U expandida"></td><td class="${th?'hidden-by-rule':''}"><input class="control eca-correction" type="number" step="any" value="${r.correction??''}" placeholder="Corrección"></td><td class="${th?'hidden-by-rule':''}"><label class="checkline"><input class="eca-apply-correction" type="checkbox" ${r.applyCorrection?'checked':''}> Aplicar</label></td></tr>`).join('')};
