 const refreshDosimeterTimeline=()=>{if(!window.ecDosimeterTimeline)return;const arr=[...dosimeterHistoryParsed].sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')));ecDosimeterTimeline.innerHTML=arr.length?`<b>Historial leído (${arr.length}):</b> ${arr.map(p=>`<span style="display:inline-block;margin:3px 8px 3px 0"><b>${esc(p.certificateNumber||'Sin número')}</b> · ${p.date?dateTxt(p.date):'fecha no detectada'} · ${dosimeterUsefulRows(p).length} punto(s) clave · Ajuste ${p.adjusted?'SÍ':'NO'}</span>`).join(' → ')}`:'<b>Historial:</b> aún no se han leído certificados anteriores.';};
 const readPreviousFlow=async()=>{try{ecReadPrevFlow.disabled=true;ecPrevFlowMsg.textContent=flowFamily()?'Leyendo certificado anterior del anemómetro…':'Leyendo certificado anterior TetraCal…';const file=ecPrevFlowPdf.files[0];if(!file)throw new Error('Seleccione el certificado anterior PDF.');const parsed=flowFamily()?parseAnemometerCertificate(await extractPdfCertificatePages(file)):parseTetraCalCertificate(await extractPdfCertificatePages(file));if(!parsed.rows.length)throw new Error('No pude reconocer puntos multipunto comparables en el certificado anterior.');flowPrevParsed=parsed;if(flowFamily()){anemoPrevDateInput.value=parsed.date||'';syncAnemoDates()}ecPrevFlowMsg.innerHTML=`✓ Antecedente leído: <b>${esc(parsed.certificateNumber||'sin número detectado')}</b>${parsed.date?' · Fecha de calibración '+dateTxt(parsed.date):' · ⚠ FECHA NO DETECTADA: complétela abajo'} · ${parsed.rows.length} nivel(es).`;ecPrevFlowMsg.style.color='#067647';lastIntervalEval=null;if(flowCurrentParsed)setTimeout(()=>calculateInterval(),20);}catch(err){ecPrevFlowMsg.textContent=err.message||String(err);ecPrevFlowMsg.style.color='#b42318';}finally{ecReadPrevFlow.disabled=false}};
 ecReadPrevFlow.onclick=readPreviousFlow;
 const readPreviousTgbh=async()=>{try{ecReadPrevTgbh.disabled=true;ecPrevTgbhMsg.textContent='Leyendo certificado anterior EI-198…';const file=ecPrevTgbhPdf.files[0];if(!file)throw new Error('Seleccione el certificado anterior PDF.');const struct=await extractPdfCertificatePages(file),parsed=parseTgbhCalibrationCertificate(struct);if(!parsed.rows.length)throw new Error('No pude reconocer puntos TGBH comparables en el certificado anterior.');tgbhPrevParsed=parsed;ecPrevTgbhMsg.innerHTML=`✓ Antecedente leído: <b>${esc(parsed.certificateNumber||'—')}</b> · ${parsed.date?dateTxt(parsed.date):'sin fecha'} · ${parsed.rows.length} punto(s).`;ecPrevTgbhMsg.style.color='#067647';ecTgbhPair.innerHTML=`<b>Histórico:</b> ${esc(parsed.certificateNumber||'—')} → <b>Actual:</b> ${esc(tgbhCurrentParsed?.certificateNumber||ecNumber.value||'pendiente')}. La IA comparará solo magnitud + punto idénticos.`;lastIntervalEval=null;if(tgbhCurrentParsed)setTimeout(()=>calculateInterval(),20)}catch(err){ecPrevTgbhMsg.textContent=err.message||String(err);ecPrevTgbhMsg.style.color='#b42318'}finally{ecReadPrevTgbh.disabled=false}};
