function openProgramPlanModal(i){
 const person=i.modality==='INTERNAL'?i.who:'';const provider=i.modality==='EXTERNAL'?i.provider:'';
 document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop open" id="programPlanModal"><div class="modal small"><div class="modal-head"><div><h2>Planificar ${esc(humanType(i.type).toLowerCase())}</h2><p>${esc(i.equipment.code)} · ${esc(i.equipment.name)} · ${esc(humanMod(i.modality))}</p></div><button class="close-btn" id="closeProgramPlan">×</button></div><div class="modal-body"><div class="form-grid"><div class="field span-3"><label>Fecha programada *</label><input id="ppDate" type="date" class="control" value="${esc(i.dueDate||i.suggestedDate||'')}"></div>${i.modality==='INTERNAL'?`<div class="field span-3"><label>Responsable</label><input id="ppAssigned" class="control" value="${esc(person)}" placeholder="Persona / rol responsable"></div>`:`<div class="field span-3"><label>Proveedor / laboratorio externo</label><input id="ppProvider" class="control" value="${esc(provider)}" placeholder="Proveedor por confirmar o contratado"></div>`}<div class="field span-3"><label>Prioridad manual <span class="optional-tag">opcional</span></label><select id="ppPriority" class="control"><option value="">Automática por IA</option>${['CRITICA','ALTA','MEDIA','BAJA'].map(x=>`<option value="${x}" ${i.override?.priorityOverride===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field span-3"><label>Observación de planificación</label><textarea id="ppNotes" class="control" placeholder="Motivo de reprogramación, coordinación, condición operativa...">${esc(i.notes)}</textarea></div></div><div class="info-banner"><b>Planificación, no ejecución:</b> esta fecha organiza el trabajo. El resultado real se registrará posteriormente en el módulo específico y reemplazará automáticamente la próxima fecha cuando corresponda.</div><div id="ppMsg" class="form-msg"></div></div><div class="modal-foot"><button class="btn btn-secondary" id="cancelProgramPlan">Cancelar</button><button class="btn btn-primary" id="saveProgramPlanBtn">Guardar planificación</button></div></div></div>`);
 const close=()=>programPlanModal.remove();closeProgramPlan.onclick=close;cancelProgramPlan.onclick=close;
 saveProgramPlanBtn.onclick=async()=>{if(!ppDate.value){ppMsg.textContent='Seleccione una fecha programada.';ppMsg.classList.add('bad');return}saveProgramPlanBtn.disabled=true;ppMsg.textContent='Guardando planificación multi-PC…';try{await saveProgramPlan({equipmentId:i.equipment.id,equipmentCode:i.equipment.code,equipmentName:i.equipment.name,controlType:i.type,modality:i.modality,scopeKey:i.scopeKey||'',plannedDate:ppDate.value,assignedTo:i.modality==='INTERNAL'?ppAssigned.value:'',provider:i.modality==='EXTERNAL'?ppProvider.value:'',priorityOverride:ppPriority.value,notes:ppNotes.value},currentUser);close()}catch(err){ppMsg.textContent=err.message;ppMsg.classList.add('bad');saveProgramPlanBtn.disabled=false}}
}
function normalizeControlType(type){
 const t=String(type||'').toUpperCase();
 if(['CALIBRACION','CALIBRATION'].includes(t))return 'CALIBRATION';
 if(['VERIFICACION','VERIFICATION'].includes(t))return 'VERIFICATION';
 if(['MANTENIMIENTO','MAINTENANCE'].includes(t))return 'MAINTENANCE';
 return t;
}
const CONTROL_MODULE_REGISTRY={
 VERIFICATION:{INTERNAL:{available:true,page:'verificationInternal',label:'Verificación Interna'},EXTERNAL:{available:true,page:'external',label:'Controles Externos'}},
 CALIBRATION:{INTERNAL:{available:true,page:'calibrationInternal',label:'Calibración Interna'},EXTERNAL:{available:true,page:'external',label:'Controles Externos'}},
 MAINTENANCE:{INTERNAL:{available:true,page:'maintenanceInternal',label:'Mantenimiento Interno'},EXTERNAL:{available:true,page:'external',label:'Controles Externos'}}
};
function programTaskFor(e,type,modality){
 const t=normalizeControlType(type),m=String(modality||'').toUpperCase();
 return buildProgramItems().find(x=>x.equipment.id===e.id&&x.type===t&&x.modality===m)||null;
}
function routeControlModule(e,type,modality,{source='PROGRAM'}={}){
 const t=normalizeControlType(type),m=String(modality||'INTERNAL').toUpperCase();
 const cfg=CONTROL_MODULE_REGISTRY[t]?.[m];
 const task=programTaskFor(e,t,m);
 if(!cfg?.available)return openModulePendingNotice(e,t,m,source,task);
 if(m==='EXTERNAL'){
  currentPage='external'; renderApp();
  setTimeout(()=>{const i=programTaskFor(e,t,'EXTERNAL'); if(i)openExternalControlModal(i);},0);
  return;
 }
 if(t==='VERIFICATION'&&m==='INTERNAL'){
  currentPage='verificationInternal'; renderApp();
  setTimeout(()=>{const i=programTaskFor(e,t,'INTERNAL'); if(i)openSmartVerification(i); else openModulePendingNotice(e,t,m,source,null);},0);
  return;
 }
 if(t==='CALIBRATION'&&m==='INTERNAL'){
  currentPage='calibrationInternal'; renderApp();
  setTimeout(()=>{const list=buildProgramItems().filter(x=>x.equipment.id===e.id&&x.type==='CALIBRATION'&&x.modality==='INTERNAL'); if(list.length===1)openInternalCalibration(list[0]); else if(list.length>1)showGlobalToast('<b>Calibraciones internas múltiples.</b><br>Seleccione el método correspondiente en el módulo Calibración Interna.','warning'); else openModulePendingNotice(e,t,m,source,null);},0);
  return;
 }
 if(t==='MAINTENANCE'&&m==='INTERNAL'){
  currentPage='maintenanceInternal'; renderApp();
  setTimeout(()=>{const i=programTaskFor(e,t,'INTERNAL'); if(i)openInternalMaintenance(i); else openModulePendingNotice(e,t,m,source,null);},0);
  return;
 }
 openModulePendingNotice(e,t,m,source,task);
}
function runProgramRoute(i){
 if(i?.type==='CALIBRATION'&&i?.modality==='INTERNAL'){currentPage='calibrationInternal';renderApp();setTimeout(()=>openInternalCalibration(i),0);return}
 return routeControlModule(i.equipment,i.type,i.modality,{source:'PROGRAM'});
}
function openModulePendingNotice(e,type,modality,source='PROGRAM',task=null){
 const t=normalizeControlType(type),human=humanType(t),mod=String(modality||'INTERNAL').toUpperCase();
 const moduleName=CONTROL_MODULE_REGISTRY[t]?.[mod]?.label||`${human} ${mod==='INTERNAL'?'Interna':'Externa'}`;
 document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop open" id="internalRouteModal"><div class="modal small"><div class="modal-head"><div><h2>Módulo pendiente de desarrollo</h2><p>${esc(e.code)} · ${esc(moduleName)}</p></div><button class="close-btn" id="closeInternalRoute">×</button></div><div class="modal-body"><div class="integrity"><strong>⏳</strong><span>La obligación ya está conectada al flujo maestro, pero su formulario ejecutor aún no ha sido desarrollado.</span></div><div class="smart-task"><div><b>No se abrirá un formulario genérico</b><small>Para evitar doble digitación y registros inconsistentes, esta Ruta Inteligente esperará al módulo específico de ${esc(human.toLowerCase())} ${mod==='INTERNAL'?'interna':'externa'}.</small></div></div><div class="info-banner"><b>Conexión reservada:</b> cuando el módulo se construya, esta misma acción “Ir a completar” lo abrirá directamente. Al cerrar su ejecución, actualizará Programa Metrológico → Expediente → Historial → Inventario → Alertas/IA.</div></div><div class="modal-foot">${task?'<button class="btn btn-secondary" id="goPlanFromRoute">Planificar / reprogramar</button>':''}<button class="btn btn-primary" id="closeInternalRoute2">Entendido</button></div></div></div>`);
 const close=()=>internalRouteModal.remove();closeInternalRoute.onclick=close;closeInternalRoute2.onclick=close;
 if(task&&document.getElementById('goPlanFromRoute'))goPlanFromRoute.onclick=()=>{close();openProgramPlanModal(task)};
}
function openProgramInsight(i){
 const next=i.dueDate?dateTxt(i.dueDate):'sin fecha definida';
 document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop open" id="programInsightModal"><div class="modal small"><div class="modal-head"><div><h2>🤖 Análisis metrológico · ${esc(i.equipment.code)}</h2><p>${esc(humanType(i.type))} ${esc(humanMod(i.modality).toLowerCase())}</p></div><button class="close-btn" id="closeProgramInsight">×</button></div><div class="modal-body"><div class="program-insight-score"><strong>${esc(i.priority)}</strong><span>Prioridad calculada · riesgo ${i.risk}/100</span></div><h3>Por qué aparece aquí</h3>${i.reasons.length?i.reasons.map(r=>`<div class="risk-item">${esc(r)}</div>`).join(''):'<div class="ok-item">Actividad planificada sin factores críticos.</div>'}<div class="view-grid"><div class="view-item"><label>Próxima / planificada</label><div>${esc(next)}</div></div><div class="view-item"><label>Última evidencia</label><div>${i.lastDate?dateTxt(i.lastDate):'SIN EJECUCIÓN'}</div></div><div class="view-item"><label>Frecuencia</label><div>${i.frequency?i.frequency+' meses':'Sin frecuencia'}</div></div><div class="view-item"><label>Responsable</label><div>${esc(i.modality==='INTERNAL'?(i.who||'Por definir'):(i.provider||'Por definir'))}</div></div></div><div class="info-banner"><b>IA explicable:</b> la prioridad es una ayuda preventiva; no cambia criterios técnicos ni declara conformidad. La decisión y ejecución pertenecen al módulo técnico correspondiente.</div></div><div class="modal-foot"><button class="btn btn-secondary" id="planFromInsight">Planificar</button><button class="btn btn-primary" id="routeFromInsight">${esc(programActionLabel(i))}</button></div></div></div>`);
 const close=()=>programInsightModal.remove();closeProgramInsight.onclick=close;planFromInsight.onclick=()=>{close();openProgramPlanModal(i)};routeFromInsight.onclick=()=>{close();runProgramRoute(i)};
}
function openProgramFlow(){
 document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop open" id="programFlowModal"><div class="modal"><div class="modal-head"><div><h2>🧭 Flujo metrológico maestro</h2><p>Arquitectura que conservarán todos los módulos futuros.</p></div><button class="close-btn" id="closeProgramFlow">×</button></div><div class="modal-body"><div class="flow-chain"><div><b>1. Inventario Maestro</b><span>Define qué control aplica, modalidad y frecuencia.</span></div><i>→</i><div><b>2. Programa Metrológico</b><span>Planifica, prioriza y muestra todo lo pendiente.</span></div><i>→</i><div><b>3. Módulo ejecutor</b><span>Formulario específico interno o evidencia externa.</span></div><i>→</i><div><b>4. Expediente</b><span>Archiva el documento y conserva revisiones.</span></div><i>→</i><div><b>5. Historial</b><span>Recibe automáticamente el evento ocurrido.</span></div></div><div class="info-banner"><b>Sin doble digitación:</b> Programa Metrológico no es un formulario de resultados. Cuando construyamos Mantenimiento Interno, Calibración Interna y Verificación Interna, sus cierres alimentarán este programa automáticamente. Los procesos externos seguirán entrando por PDF/enlace y también cerrarán su actividad asociada.</div></div></div></div>`);closeProgramFlow.onclick=()=>programFlowModal.remove();
}


// ========================= V0.6.1 · VERIFICACIÓN INTERNA INTELIGENTE AVANZADA =========================
function verificationProfile(e){
 const forced=String(e?.plans?.verification?.profile||'AUTO').toUpperCase();
 if(forced && forced!=='AUTO') return forced;
 const hay=[e?.name,e?.intendedUse,e?.technical?.methodPrinciple,e?.plans?.verification?.uvParameter,...(e?.metrologicalCharacteristics||[]).flatMap(x=>[x.magnitude,x.unit,x.workingRange])].join(' ').toLowerCase();
 if(/vibromet|vibracion|vibración|sv[-\s]*106|sv106|ei[-\s]*176|mano[-\s]*brazo|cuerpo entero|aceleromet/.test(hay))return 'VIBRATION';
 if(/dos[ií]metro|dosimeter|sv\s*104|dosimetr[ií]a/.test(hay))return 'DOSIMETER';
 if(/uv.?visible|espectrofot|absorbancia|hierro|curva/.test(hay))return 'UV_VISIBLE';
 if(/balanza|báscula|bascula|masa|peso/.test(hay))return 'BALANCE';
 if(/phmetro|ph metro|potencial de hidrogeno|potencial de hidrógeno/.test(hay))return 'PH';
 if(/conduct|µs|us\/cm|ms\/cm/.test(hay))return 'CONDUCTIVITY';
 if(/cron[oó]metro|temporizador|timer|tiempo/.test(hay))return 'TIME';
 if(/pipeta|bureta|matraz|dispensador|volumen/.test(hay))return 'VOLUME';
 if(/temperatura|term[oó]metro|incubadora|estufa|horno|baño|bano|nevera|refriger|plato calentador|calentador/.test(hay))return 'TEMPERATURE';
 return 'GENERIC';
}
function profileName(p){return ({DOSIMETER:'Dosímetro acústico',VIBRATION:'Vibraciones HAV / WBV',BALANCE:'Masa / balanza',TEMPERATURE:'Temperatura',UV_VISIBLE:'UV-VISIBLE',PH:'pH',CONDUCTIVITY:'Conductividad',TIME:'Tiempo',VOLUME:'Volumen',GENERIC:'Verificación general'})[p]||'Verificación general'}
function verificationSequence(e,date){
 const year=String(date||isoToday()).slice(0,4);
 // El código del equipo ya contiene su prefijo (ej. EI-21), por eso no se antepone otro "EI".
 // Formato definitivo: IV-{CODIGO_EQUIPO}-{AÑO}-{SECUENCIA} → IV-EI-21-2026-001.
 const prefix=`IV-${e.code}-${year}-`;
 // Compatibilidad con registros históricos que usaban IV-EI-EI-XX-AÑO-001:
 // para calcular la siguiente secuencia solo tomamos el consecutivo final del mismo equipo/año.
 const nums=dossier
  .filter(d=>d.equipmentId===e.id&&d.category==='VERIFICACION_INTERNA')
  .map(d=>String(d.generatedData?.verificationCode||d.verificationCode||''))
  .filter(code=>code.startsWith(prefix))
  .map(code=>{const m=code.match(/-(\d{3,})$/);return m?parseInt(m[1],10):0;});
 return `${prefix}${String(Math.max(0,...nums)+1).padStart(3,'0')}`;
}
function parsedConfiguredPoints(e){
 const v=e?.plans?.verification||{}; let arr=[];
 if(v.strategy==='FIJO'&&v.fixedPoint) arr=[v.fixedPoint];
 else if(v.strategy==='DEFINIDOS'&&v.definedPoints) arr=String(v.definedPoints).split(/[,;\n]|\sy\s/i).map(x=>x.trim()).filter(Boolean);
 if(!arr.length){
   const chars=e?.metrologicalCharacteristics||[];
   arr=chars.flatMap(c=>String(c.controlPoints||'').split(/[,;\n]|\sy\s/i).map(x=>x.trim()).filter(Boolean));
 }
 if(!arr.length&&verificationProfile(e)==='DOSIMETER')arr=['1000 Hz / 94 dB'];
 if(!arr.length&&verificationProfile(e)==='VIBRATION')arr=['Punto nominal del calibrador de vibraciones'];
 return [...new Set(arr)];
}
function intelligentVerificationCriterion(e,p){
 const v=e?.plans?.verification||{}; const chars=e?.metrologicalCharacteristics||[];
 const explicit=String(v.acceptanceCriterion||'').trim(); if(explicit&&!(p==='DOSIMETER'&&/^5\s*d?b/i.test(explicit)))return explicit;
 const charCriterion=chars.map(x=>x.acceptanceCriterion).find(Boolean); if(charCriterion)return charCriterion;
 const emp=chars.map(x=>x.empCriterion||x.accuracyEmp).find(Boolean); if(emp)return `Error absoluto dentro del EMP configurado: ${emp}`;
 if(p==='DOSIMETER'){
   const low=explicit.toLowerCase();
   if(!explicit||/^5\s*d?b/i.test(explicit))return '±1,0 dB @ 1000 Hz / 94 dB — criterio sugerido; confirmar contra el procedimiento interno vigente.';
  }
 if(p==='VIBRATION')return 'Diferencia porcentual ≤ 5 % del valor nominal del calibrador certificado; confirmar contra el procedimiento interno vigente.';
 if(p==='TEMPERATURE')return 'Defina en la ficha el EMP/tolerancia permitida para temperatura antes de concluir la verificación.';
 if(p==='BALANCE')return 'Defina en la ficha el EMP/tolerancia permitida para masa antes de concluir la verificación.';
 if(p==='UV_VISIBLE')return 'Defina en la ficha el criterio del punto de curva (tolerancia, recuperación o desviación permitida) antes de concluir la verificación.';
 return 'Defina el criterio técnico vigente en la ficha del equipo antes de concluir la verificación.';
}
function numericToleranceFromCriterion(text=''){
 const raw=String(text??'').trim().replace(/,/g,'.');
 if(!raw)return null;
 // Acepta expresiones explícitas (±2, <=2, ≤2) y también un único valor numérico ("2" o "2 °C").
 let m=raw.match(/(?:≤|<=|<|±|\+\/-|max(?:imo|imum)?(?:\s+permitido)?|tolerancia|l[ií]mite)\s*[:=]?\s*([0-9]+(?:\.[0-9]+)?)/i);
 if(m)return Number(m[1]);
 const nums=[...raw.matchAll(/-?[0-9]+(?:\.[0-9]+)?/g)].map(x=>Number(x[0])).filter(Number.isFinite);
 return nums.length===1?Math.abs(nums[0]):null;
}
function compactLimitLabel(text,tol,unit=''){
 if(String(text||'').trim())return String(text).trim();
 return Number.isFinite(tol)?`±${tol}${unit?' '+unit:''}`:'No definido';
}
function suggestVerificationDecision(rows,criterion,accreditation=''){
 const tol=numericToleranceFromCriterion(criterion), accTol=numericToleranceFromCriterion(accreditation);
 const errs=rows.map(r=>Math.abs(Number(String(r.error).replace(',','.')))).filter(Number.isFinite);
 if(!errs.length)return {decision:'',reason:'Ingrese lecturas para evaluar el criterio.',tolerance:tol,accreditationTolerance:accTol,maxError:null,accreditationStatus:''};
 const max=Math.max(...errs);
 if(!Number.isFinite(tol)){
   const accStatus=Number.isFinite(accTol)?(max<=accTol?'CUMPLE':'EXCEDE'):'';
   return {decision:'',reason:`Máximo |error| = ${max}. No se identificó un límite de aceptación numérico inequívoco.${accStatus?` Límite de acreditación: ${accStatus}.`:''}`,tolerance:tol,accreditationTolerance:accTol,maxError:max,accreditationStatus:accStatus};
 }
 const ok=errs.every(x=>x<=tol), accStatus=Number.isFinite(accTol)?(max<=accTol?'CUMPLE':'EXCEDE'):'';
 const accMsg=accStatus?` Límite de acreditación ${accTol}: ${accStatus}.`:'';
 return {decision:ok?'CONFORME':'NO CONFORME',reason:`Máximo |error| = ${max}; límite de aceptación interpretado = ${tol}.${accMsg}`,tolerance:tol,accreditationTolerance:accTol,maxError:max,accreditationStatus:accStatus};
}
function suggestVibrationVerificationDecision(rows){
 const complete=rows.map(r=>{const ref=Number(String(r.reference||'').replace(',','.')),ind=Number(String(r.indicated||'').replace(',','.'));if(!Number.isFinite(ref)||!Number.isFinite(ind)||ref===0)return null;const pct=Math.abs(ind-ref)/Math.abs(ref)*100;return {ref,ind,pct}}).filter(Boolean);
 if(!complete.length)return {decision:'',reason:'Ingrese valor nominal y lectura del vibrómetro para calcular la diferencia porcentual.',tolerance:5,accreditationTolerance:null,maxError:null,accreditationStatus:''};
 const max=Math.max(...complete.map(x=>x.pct));
 return {decision:max<=5?'CONFORME':'NO CONFORME',reason:`Máxima diferencia porcentual = ${max.toFixed(2)} %; criterio ≤ 5 %.`,tolerance:5,accreditationTolerance:null,maxError:max,accreditationStatus:''};
}
function verificationLabels(p){
 return ({
  DOSIMETER:{ref:'Nivel de referencia',ind:'Indicación del dosímetro',unit:'dB(A)',reference:'Calibrador acústico / patrón'},
  VIBRATION:{ref:'Valor nominal del calibrador',ind:'Lectura del vibrómetro',unit:'m/s²',reference:'Calibrador de vibraciones certificado'},
  BALANCE:{ref:'Masa patrón',ind:'Indicación de la balanza',unit:'g',reference:'Pesa/patrón utilizado'},
  TEMPERATURE:{ref:'Valor de referencia',ind:'Lectura del equipo',unit:'°C',reference:'Patrón de referencia'},
  UV_VISIBLE:{ref:'Valor nominal / punto de curva',ind:'Resultado obtenido',unit:'',reference:'Patrón / solución de referencia'},
  PH:{ref:'Valor de referencia/buffer',ind:'Lectura del equipo',unit:'pH',reference:'Buffer/MRC de pH'},
  CONDUCTIVITY:{ref:'Valor de referencia',ind:'Lectura del equipo',unit:'µS/cm',reference:'Patrón/MRC de conductividad'},
  TIME:{ref:'Tiempo de referencia',ind:'Tiempo indicado',unit:'s',reference:'Cronómetro/patrón de referencia'},
  VOLUME:{ref:'Volumen de referencia',ind:'Volumen obtenido/indicado',unit:'mL',reference:'Patrón/referencia volumétrica'},
  GENERIC:{ref:'Valor de referencia',ind:'Indicación/resultado del equipo',unit:'',reference:'Patrón / referencia utilizada'}
 })[p];
}
function internalVerificationItems(){return buildProgramItems().filter(i=>i.type==='VERIFICATION'&&i.modality==='INTERNAL')}
function renderVerificationInternal(){
 const all=internalVerificationItems();
 const withEvidence=all.filter(i=>i.evidence).length, pending=all.filter(i=>!i.evidence).length, due=all.filter(i=>['VENCIDA','HOY','PROXIMA'].includes(i.status)).length;
 const content=`<section class="content verification-page"><div class="module-title"><div><h1>Verificación Interna Inteligente</h1><p>Formulario mínimo y contextual según el equipo. Registra únicamente la evidencia necesaria de la verificación; no replica formatos de calibración ni mantenimiento.</p></div></div>
 <div class="kpis"><div class="kpi"><strong>${all.length}</strong><span>Equipos con verificación interna</span></div><div class="kpi"><strong>${withEvidence}</strong><span>Con verificación vigente</span></div><div class="kpi kpi-warning"><strong>${pending}</strong><span>Sin ejecución</span></div><div class="kpi kpi-danger"><strong>${due}</strong><span>Vencidas / próximas</span></div></div>
 <div class="program-ai"><div class="program-ai-head"><div><b>🤖 Asistente de verificación contextual</b><span>Reconoce el tipo de equipo por su ficha y propone solo los campos pertinentes. La decisión técnica final siempre la registra el analista.</span></div></div><div class="program-ai-grid">${all.map((i,n)=>`<button class="program-ai-card smartVerify" data-task="${i.id}"><span>${n+1}</span><div><b>${esc(i.equipment.code)} · ${esc(i.equipment.name)}</b><small>${esc(profileName(verificationProfile(i.equipment)))} · ${i.evidence?'Última '+dateTxt(i.lastDate):'Sin verificación registrada'} · ${esc(i.status.replace('_',' '))}</small></div><strong>Ejecutar →</strong></button>`).join('')||'<div class="ok-item">No hay verificaciones internas configuradas en Inventario.</div>'}</div></div>
 <div class="panel"><div class="table-wrap"><table class="program-table"><thead><tr><th>Equipo</th><th>Perfil inteligente</th><th>Frecuencia</th><th>Última</th><th>Próxima</th><th>Estado</th><th>Responsable</th><th>Acciones</th></tr></thead><tbody>${all.map(i=>`<tr><td><b class="code">${esc(i.equipment.code)}</b><small>${esc(i.equipment.name)} · ${esc(i.equipment.location||'')}</small></td><td><b>${esc(profileName(verificationProfile(i.equipment)))}</b><small>${i.strategy?esc(i.strategy.replaceAll('_',' ')):''}${i.pointsCount?' · '+i.pointsCount+' punto(s)':''}</small></td><td>${i.frequency?i.frequency+' meses':(i.conditionOnly?'Por condición/falla':'Sin frecuencia')}</td><td>${i.lastDate?dateTxt(i.lastDate):'<span class="doc-missing">SIN EJECUCIÓN</span>'}</td><td>${i.dueDate?dateTxt(i.dueDate):(i.conditionOnly?'<span class="program-state program-info">NO APLICA</span>':'<span class="doc-missing">SIN FECHA</span>')}</td><td>${programStatusBadge(i.status)}</td><td>${esc(i.who||'Por definir')}</td><td><div class="row-actions"><button class="icon-btn smartVerify" data-task="${i.id}">Ejecutar</button><button class="icon-btn verifyDossier" data-eqid="${i.equipment.id}">Expediente</button></div></td></tr>`).join('')||'<tr><td colspan="8" class="empty-row">Configure una verificación interna desde Inventario Maestro.</td></tr>'}</tbody></table></div></div>
 <div class="info-banner"><b>Flujo:</b> Inventario define frecuencia/estrategia → Programa Metrológico planifica → Verificación Interna registra datos mínimos → genera PDF → Expediente archiva → Inventario actualiza Última/Próxima → Programa recalcula automáticamente.</div></section>`;
 shell(content,'Verificación Interna','Ejecución contextual por tipo de equipo · trazabilidad breve · PDF automático');
 document.querySelectorAll('.smartVerify').forEach(b=>b.onclick=()=>{const i=all.find(x=>x.id===b.dataset.task);if(i)openSmartVerification(i)});
 document.querySelectorAll('.verifyDossier').forEach(b=>b.onclick=()=>{currentPage='dossier';filters.dq=equipment.find(e=>e.id===b.dataset.eqid)?.code||'';renderApp()});
}
function safePdfString(v=''){return String(v??'')
 .replace(/≤/g,'<=')
 .replace(/≥/g,'>=')
 .replace(/[µμ]/g,'u')
 .replace(/±/g,'+/-')
 .replace(/√/g,'sqrt')
 .replace(/Δ/g,'Delta')
 .replace(/δ/g,'delta')
 .replace(/→/g,'->')
 .replace(/←/g,'<-')
 .replace(/×/g,'x')
 .replace(/÷/g,'/')
 .replace(/−/g,'-')
 .replace(/[–—]/g,'-')
 .replace(/²/g,'^2')
 .replace(/³/g,'^3')
 .replace(/✓/g,'CUMPLE')
 .replace(/✅/g,'CUMPLE')
 .replace(/❌/g,'NO CUMPLE')
 .replace(/Ȳ/g,'Yprom')
 .replace(/X̄/g,'Xprom')
 .replace(/[^\x09\x0A\x0D\x20-\x7E\xA0-\xFF]/g,'?')}
async function buildVerificationPdf(i,data){
 const e=i.equipment, lab=verificationLabels(data.profile);
 const pdf=await PDFDocument.create();
 const font=await pdf.embedFont(StandardFonts.Helvetica), bold=await pdf.embedFont(StandardFonts.HelveticaBold);
 const blue=rgb(.10,.36,.60), light=rgb(.90,.95,.985), dark=rgb(.10,.16,.24), gray=rgb(.36,.42,.49), line=rgb(.70,.76,.82), green=rgb(.10,.55,.32), red=rgb(.72,.16,.12);
 let logo=null;
 try{
   const logoBytes=await fetch(new URL('/psi-logo.jpeg',window.location.origin)).then(r=>r.arrayBuffer());
   logo=await pdf.embedJpg(logoBytes);
 }catch(_){}
 let page,y,pageNo=0;
 const wrapped=(value,width,size=8,f=font)=>{
   const words=safePdfString(value??'').split(/\s+/).filter(Boolean), out=[]; let cur='';
   for(const w of words){
     const test=cur?`${cur} ${w}`:w;
     if(cur && f.widthOfTextAtSize(test,size)>width){out.push(cur);cur=w}else cur=test;
   }
   if(cur)out.push(cur);
   return out.length?out:[''];
 };
 const addPage=()=>{
   page=pdf.addPage([595.28,841.89]); pageNo++; y=728;
   // Encabezado alineado en tres bloques: logo | institución/título | registro/página.
   const hx=36, hy=758, hw=523, hh=60, logoW=78, rightW=132;
   const logoX=hx, centerX=hx+logoW, rightX=hx+hw-rightW;
   page.drawRectangle({x:hx,y:hy,width:hw,height:hh,borderColor:blue,borderWidth:1});
   page.drawLine({start:{x:centerX,y:hy},end:{x:centerX,y:hy+hh},thickness:.6,color:line});
   page.drawLine({start:{x:rightX,y:hy},end:{x:rightX,y:hy+hh},thickness:.6,color:line});
   if(logo){
     const dims=logo.scale(1), maxW=62, maxH=38, scale=Math.min(maxW/dims.width,maxH/dims.height);
     const w=dims.width*scale, h=dims.height*scale;
     page.drawImage(logo,{x:logoX+(logoW-w)/2,y:hy+(hh-h)/2,width:w,height:h});
   }
   const centerW=rightX-centerX;
   const centerText=(txt,yPos,size,color=dark)=>{
     const t=safePdfString(txt), tw=bold.widthOfTextAtSize(t,size);
     page.drawText(t,{x:centerX+(centerW-tw)/2,y:yPos,size,font:bold,color});
   };
   centerText('LABORATORIO DE ANALISIS AMBIENTAL DE',hy+41,8.5);
   centerText('PRODUCTOS Y SERVICIOS INDUSTRIALES C. LTDA',hy+29,8.5);
   centerText('Registro de Verificacion Interna',hy+12,10.2,blue);
   page.drawText('Registro N°',{x:rightX+12,y:hy+40,size:7,font:bold,color:gray});
   wrapped(data.verificationCode||'-',rightW-24,7.4,bold).slice(0,2).forEach((ln,k)=>page.drawText(ln,{x:rightX+12,y:hy+28-k*9,size:7.4,font:bold,color:dark}));
   page.drawText(`Pagina ${pageNo}`,{x:rightX+rightW-54,y:hy+6,size:6.7,font,color:gray});
 };
 const footer=()=>{
   const pages=pdf.getPages();
   pages.forEach((pg,idx)=>{
     pg.drawLine({start:{x:38,y:42},end:{x:557,y:42},thickness:.6,color:blue});
     pg.drawText(`${safePdfString(data.verificationCode||'Registro de verificacion interna')} | ${dateTxt(data.date)}`,{x:40,y:27,size:6.8,font,color:gray});
     pg.drawText(`Pagina ${idx+1} de ${pages.length}`,{x:495,y:27,size:6.8,font,color:gray});
   });
 };
 const ensure=(h=40)=>{if(y-h<58)addPage();};
 const section=(title)=>{
   ensure(30);
   page.drawText(safePdfString(title),{x:40,y,size:10.5,font:bold,color:blue});
   page.drawLine({start:{x:40,y:y-4},end:{x:555,y:y-4},thickness:1,color:blue});
   y-=22;
 };
 const paragraph=(value,size=8.1,f=font,color=dark)=>{
   const lines=wrapped(value,510,size,f); ensure(lines.length*(size+3)+10);
   for(const ln of lines){page.drawText(ln,{x:42,y,size,font:f,color});y-=size+3;}
   y-=5;
 };
 const table=(headers,rows,widths,{fontSize=7.2,headSize=6.8}={})=>{
   const x0=40,total=widths.reduce((a,b)=>a+b,0), pad=4, headH=23;
   ensure(headH+30);
   page.drawRectangle({x:x0,y:y-headH+4,width:total,height:headH,borderColor:blue,borderWidth:.5,color:blue});
   let x=x0;
   headers.forEach((h,j)=>{
     const hLines=wrapped(h,widths[j]-pad*2,headSize,bold).slice(0,2);
     hLines.forEach((ln,k)=>page.drawText(ln,{x:x+pad,y:y-9-k*8,size:headSize,font:bold,color:rgb(1,1,1)}));
     x+=widths[j];
   });
   y-=headH-4;
   for(const row of rows){
     const cells=row.map((c,j)=>wrapped(c,widths[j]-pad*2,fontSize,font));
     const maxLines=Math.max(1,...cells.map(a=>a.length));
     const rowH=Math.max(22,maxLines*(fontSize+2)+9);
     ensure(rowH+5);
     x=x0;
     page.drawRectangle({x:x0,y:y-rowH+4,width:total,height:rowH,borderColor:line,borderWidth:.45});
     for(let j=0;j<row.length;j++){
       const lines2=cells[j].slice(0,6);
       lines2.forEach((ln,k)=>page.drawText(ln,{x:x+pad,y:y-9-k*(fontSize+2),size:fontSize,font,color:dark}));
       if(j<row.length-1)page.drawLine({start:{x:x+widths[j],y:y+4},end:{x:x+widths[j],y:y-rowH+4},thickness:.35,color:line});
       x+=widths[j];
     }
     y-=rowH;
   }
   y-=10;
 };
 addPage();
 section('1. IDENTIFICACION DEL EQUIPO');
 table(['Campo','Informacion'],[
   ['Nombre del equipo',e.name||'-'],
   ['Codigo interno',e.code||'-'],
   ['Serie / P/N',e.technical?.serialNumber||'-'],
   ['Marca / Modelo',[e.technical?.brand,e.technical?.model].filter(Boolean).join(' / ')||'-'],
   ['Ubicacion',e.location||'-'],
   ['Responsable del equipo',e.responsible||'-']
 ],[178,337],{fontSize:7.4});
 section('2. DATOS DE LA VERIFICACION');
 table(['Campo','Informacion'],[
   ['Numero de registro',data.verificationCode||'-'],
   ['Fecha de ejecucion',dateTxt(data.date)],
   ['Ejecutado por',data.analyst||'-'],
   ['Perfil aplicado',profileName(data.profile)],
   ['Estrategia',String(data.strategy||i.strategy||'Segun configuracion').replaceAll('_',' ')],
   ['Frecuencia configurada',i.frequency?`Cada ${i.frequency} meses`:'Sin frecuencia fija en ficha'],
   ['Intervalo recomendado IA',data.verificationIntervalMonths?`${data.verificationIntervalMonths} meses`:'Pendiente / no aplica'],
   ['Proxima verificacion IA',dateTxt(data.nextDate)],
   ['Fundamento IA',data.verificationIntervalReason||'-']
 ],[178,337],{fontSize:7.4});
 section('3. PATRON / REFERENCIA');
 table(['Codigo','Patron / referencia'],[[data.referenceCode||'-',data.reference||'-']],[150,365],{fontSize:7.4});
 section('4. CRITERIOS Y LIMITES DE EVALUACION');
 const tol=numericToleranceFromCriterion(data.criterion), accTol=numericToleranceFromCriterion(data.accreditationLimit);
 const baseUnit=(data.rows||[]).map(r=>r.unit).find(Boolean)||lab.unit||'';
 table(['Elemento','Criterio configurado','Limite interpretado'],[
   ['Criterio / limite de aceptacion',data.criterion||'No registrado',Number.isFinite(tol)?`|error| <= ${tol}${baseUnit?' '+baseUnit:''}`:'Requiere evaluacion manual'],
   ['Limite de acreditacion',data.accreditationLimit||'No aplica',Number.isFinite(accTol)?`|error| <= ${accTol}${baseUnit?' '+baseUnit:''}`:'No definido / no aplica']
 ],[150,225,140],{fontSize:7.1,headSize:6.5});
 section('5. RESULTADOS');
 const resultRows=(data.rows||[]).map((r,n)=>{
   const err=Number(String(r.error).replace(',','.')), absErr=Number.isFinite(err)?Math.abs(err):NaN, unit=r.unit||lab.unit||'';
   const acceptance=Number.isFinite(tol)&&Number.isFinite(absErr)?(absErr<=tol?'CONFORME':'NO CONFORME'):'MANUAL';
   const accreditation=Number.isFinite(accTol)&&Number.isFinite(absErr)?(absErr<=accTol?'CUMPLE':'EXCEDE'):(data.accreditationLimit?'MANUAL':'N/A');
   const evalTxt=`${acceptance}${accreditation!=='N/A'?` / Acred.: ${accreditation}`:''}`;
   const withUnit=v=>`${v||'-'}${unit&&v!==''&&v!=='-'?' '+unit:''}`;
   return [String(n+1),r.setpoint||'-',withUnit(r.reference),withUnit(r.indicated),withUnit(r.error),Number.isFinite(absErr)?withUnit(String(absErr)):'-',Number.isFinite(tol)?withUnit(String(tol)):'Manual',Number.isFinite(accTol)?withUnit(String(accTol)):(data.accreditationLimit?'Manual':'N/A'),evalTxt];
 });
 table(['#','Punto',lab.ref,lab.ind,'Error','|Error|','Lim. acept.','Lim. acredit.','Evaluacion'],resultRows,[18,48,63,63,50,50,65,68,90],{fontSize:5.8,headSize:5.4});
 section('6. EVALUACION Y DECISION FINAL');
 table(['Elemento','Resultado'],[
   ['Error absoluto maximo',Number.isFinite(Number(data.aiMaxError))?`${data.aiMaxError}${baseUnit?' '+baseUnit:''}`:'No calculado'],
   ['Sugerencia IA',data.aiSuggestion||'Sin sugerencia automatica'],
   ['Evaluacion limite de acreditacion',data.accreditationStatus||(!data.accreditationLimit?'NO APLICA':'Evaluacion manual')],
   ['Fundamento IA',data.aiReason||'No aplica'],
   ['Decision final del analista',data.result||'-'],
   ['Proxima verificacion',dateTxt(data.nextDate)]
 ],[178,337],{fontSize:7.4});
 ensure(24);
 page.drawText(`Decision registrada: ${safePdfString(data.result||'-')}`,{x:42,y,size:9.2,font:bold,color:data.result==='NO CONFORME'?red:green});y-=20;
 section('7. OBSERVACIONES');
 paragraph(data.notes||'Sin observaciones adicionales.');
 section('8. RESPONSABLES');
 table(['Rol','Nombre','Firma','Fecha'],[
   ['Analista que ejecuta la verificacion',data.analyst||'-',data.signature?.signed?'Registro ejecutado':'',dateTxt(data.date)],
   ['Coordinador de Calidad (Aprobado por)','JIPSON FRANCO',data.signature?.signed?'Firma P12/PFX':'Pendiente de firma',data.signature?.signed?dateTxt(data.signature.signedAt||data.date):'']
 ],[205,145,80,85],{fontSize:7});
 if(data.signature?.signed){
   ensure(32);
   paragraph(`Documento firmado digitalmente por el Coordinador de Calidad JIPSON FRANCO. SHA-256: ${data.signature.sha256||'calculado por motor P12'}`,6.8,font,gray);
 }
 ensure(45);
 page.drawRectangle({x:40,y:y-34,width:515,height:34,borderColor:line,borderWidth:.5,color:light});
 page.drawText('Trazabilidad NextGen',{x:48,y:y-13,size:7.8,font:bold,color:blue});
 const trace='Registro generado desde la configuracion vigente del equipo y archivado automaticamente en su Expediente Digital. La sugerencia IA es un apoyo explicable y no sustituye la decision tecnica del analista.';
 wrapped(trace,495,6.6,font).slice(0,3).forEach((ln,k)=>page.drawText(ln,{x:48,y:y-24-k*8,size:6.6,font,color:gray}));
 footer();
 return new Blob([await pdf.save()],{type:'application/pdf'});
}

function verificationIntervalAi(e,p,{date='',decision='',maxError=NaN,tolerance=NaN,patternStatus='',configuredMonths=0}={}){
 const baseConfigured=Number(configuredMonths)||Number(e?.plans?.verification?.internal?.frequencyMonths)||Number(e?.plans?.verification?.internal?.frequency)||0;
 const history=dossier.filter(d=>d.equipmentId===e.id&&d.category==='VERIFICACION_INTERNA'&&d.generatedData).sort((a,b)=>String(b.issueDate||'').localeCompare(String(a.issueDate||'')));
 const prevAi=history.map(d=>Number(d.generatedData?.verificationIntervalMonths)||0).find(v=>v>0)||0;
 const base=Math.max(1,Math.min(12,baseConfigured||prevAi||(p==='DOSIMETER'?6:6)));
 const dt=date||isoToday();
 if(!decision)return {months:base,nextDate:'',reason:`Pendiente de lecturas completas. Intervalo base: ${base} meses.`};
 if((p==='DOSIMETER'||p==='VIBRATION')&&patternStatus==='NO VIGENTE')return {months:0,nextDate:'',reason:p==='DOSIMETER'?'No se programa la próxima verificación con un calibrador acústico no vigente. Debe repetirse con patrón vigente.':'No se programa la próxima verificación con un calibrador de vibraciones no vigente. Debe repetirse con patrón vigente.'};
 const ratio=Number.isFinite(Number(maxError))&&Number.isFinite(Number(tolerance))&&Number(tolerance)>0?Math.abs(Number(maxError))/Number(tolerance):NaN;
 const priorDos=history.filter(d=>d.generatedData?.profile==='DOSIMETER').slice(0,3);
 const priorErrors=priorDos.map(d=>Number(d.generatedData?.aiMaxError)).filter(Number.isFinite);
 let months=base,why=[];
 if(decision==='NO CONFORME'){months=1;why.push('resultado no conforme: reverificación temprana; la acción correctiva/calibración debe ejecutarse antes de liberar el equipo')}
 else if(decision==='VIGILANCIA'){months=Math.max(1,Math.min(3,Math.ceil(base/2)));why.push('estado de vigilancia: se reduce el intervalo para confirmar estabilidad')}
 else if(decision==='CONFORME'){
   if(Number.isFinite(ratio)&&ratio>=0.75){months=Math.max(1,Math.min(3,Math.ceil(base/2)));why.push(`utilización del criterio ${(ratio*100).toFixed(0)}%`)}
   else if(Number.isFinite(ratio)&&ratio>=0.50){months=Math.max(3,Math.min(base,6));why.push(`utilización del criterio ${(ratio*100).toFixed(0)}%: mantener vigilancia preventiva`)}
   else {months=base;why.push(Number.isFinite(ratio)?`utilización del criterio ${(ratio*100).toFixed(0)}% con resultado conforme`:'resultado conforme')}
   if(p==='DOSIMETER'&&priorErrors.length>=2&&Number.isFinite(ratio)&&ratio<0.5){
     const stable=[Number(maxError),...priorErrors.slice(0,2)].every(v=>Number.isFinite(v)&&Number(tolerance)>0&&v/Number(tolerance)<0.5);
     const increasing=priorErrors.length>=1&&Number(maxError)>priorErrors[0]+Math.max(0.05,Number(tolerance)*0.1);
     if(stable&&!increasing&&base<9){months=Math.min(9,base+1);why.push('histórico reciente estable; ampliación moderada de 1 mes')}
   }
 }
 months=Math.max(1,Math.min(12,Math.round(months)));
 return {months,nextDate:addMonthsIso(dt,months),reason:`IA de verificación: ${why.join('; ')}. Intervalo base ${base} meses. Recomendación técnica; no sustituye el criterio del responsable.`};
}

function openSmartVerification(i){
 const e=i.equipment,p=verificationProfile(e),lab=verificationLabels(p),mc=(e.metrologicalCharacteristics||[])[0]||{},isVariable=String(i.strategy||'').includes('VARIABLE');
 const configured=parsedConfiguredPoints(e); const pointCount=Math.max(1,configured.length||Number(i.pointsCount)||1), defaultUnit=mc.unit||lab.unit||'';
 const baseCriterion=intelligentVerificationCriterion(e,p); const baseAccreditation=String(e?.plans?.verification?.accreditationLimit||'').trim(); const analysts=[...new Set(['NIDIA SANCHEZ','JIPSON FRANCO','KATHERINE FLORES','LIZBETH PRIETO','MARIA ELENA ZAMBRANO',...(catalogs.verificationAnalysts||[])])];
 const patterns=catalogs.metrologyPatterns||[]; const today=isoToday(); const code=verificationSequence(e,today);
 const analystOptions=analysts.map(x=>`<option value="${esc(x)}" ${String(i.who||'').toUpperCase()===x.toUpperCase()?'selected':''}>${esc(x)}</option>`).join('');
 const patternOptions=patterns.map(x=>`<option value="${esc(x)}"></option>`).join('');
 const rowHtml=(point='')=>`<tr class="verify-row"><td><input class="control vrSet" value="${esc(point)}" placeholder="${isVariable?'Punto usado hoy':'Punto configurado'}"></td><td><input class="control vrRef" inputmode="decimal"></td><td><input class="control vrInd" inputmode="decimal"></td><td><input class="control vrErr" readonly></td><td><input class="control vrAbsErr" readonly></td><td><input class="control vrUnit" value="${esc(defaultUnit)}"></td><td><button type="button" class="icon-btn vrDel">×</button></td></tr>`;
 const rows=(configured.length?configured:Array.from({length:pointCount},()=>'' )).map(rowHtml).join('');
 document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop open" id="smartVerifyModal"><div class="modal large"><div class="modal-head"><div><h2>Verificación interna · ${esc(e.code)}</h2><p>${esc(e.name)} · Perfil: <b>${esc(profileName(p))}</b> · <b>${esc(code)}</b></p></div><button class="close-btn" id="closeSmartVerify">×</button></div><div class="modal-body">
 <div class="info-banner"><b>IA contextual:</b> el esquema se toma de la ficha vigente del equipo. Perfil <b>${esc(profileName(p))}</b>${e.plans?.verification?.uvParameter?` · ${esc(e.plans.verification.uvParameter)}`:''}. Los puntos configurados se precargan y pueden adaptarse si el procedimiento vigente lo requiere.</div>
 <div class="form-grid"><div class="field"><label>Código automático</label><input id="svCode" class="control" value="${esc(code)}" readonly></div><div class="field"><label>Fecha *</label><input id="svDate" type="date" class="control" value="${today}"></div><div class="field"><label>Ejecutado por *</label><div style="display:flex;gap:8px"><select id="svAnalyst" class="control"><option value="">Seleccione analista…</option>${analystOptions}</select><button type="button" class="icon-btn" id="addSvAnalyst">＋ Agregar</button></div></div>
 <div class="field"><label>Código del patrón *</label><input id="svReferenceCode" class="control" placeholder="${p==='DOSIMETER'?'Ej. CA-001 / CAL-AC-01':'Ej. EI-61 / PT-001'}"></div><div class="field span-2"><label>Nombre del patrón / referencia *</label><div style="display:flex;gap:8px"><input id="svReference" class="control" list="svPatternList" placeholder="${p==='DOSIMETER'?'Ej. Calibrador acústico 94 dB / 1000 Hz':'Ej. Termómetro patrón Fluke 1523'}"><datalist id="svPatternList">${patternOptions}</datalist><button type="button" class="icon-btn" id="addSvPattern">＋ Agregar</button></div></div>
 <div class="field span-2"><label>Criterio / límite de aceptación inteligente *</label><textarea id="svCriterion" class="control">${esc(baseCriterion)}</textarea><small>Puede ser “±2 °C”, “|error| ≤ 2 °C” o simplemente “2”. Si existe un único valor numérico, la IA lo interpreta como límite absoluto del error.</small></div><div class="field"><label>Límite de acreditación <span class="optional-tag">si aplica</span></label><input id="svAccreditation" class="control" value="${esc(baseAccreditation)}" placeholder="Ej. ±1,5 °C o 1,5"><small>Se evalúa por separado contra |error|.</small></div></div>
 ${p==='DOSIMETER'?`<div class="derived-box" style="margin-top:14px"><b>🎧 Verificación específica de dosímetro</b><p>Comprobación funcional breve y trazable. La IA no declara conformidad si faltan lecturas.</p><div class="form-grid"><div class="field"><label>Frecuencia del calibrador</label><input id="svDoseFrequency" class="control" value="1000" inputmode="decimal"><small>Hz</small></div><div class="field"><label>Nivel nominal</label><input id="svDoseNominal" class="control" value="94" inputmode="decimal"><small>dB</small></div><div class="field"><label>Vigencia del patrón</label><select id="svPatternStatus" class="control"><option value="">Seleccione…</option><option>VIGENTE</option><option>NO VIGENTE</option></select></div><div class="field span-3"><label>Comprobación funcional</label><div class="check-grid"><label><input type="checkbox" class="svDoseCheck" value="ENCENDIDO"> Encendido</label><label><input type="checkbox" class="svDoseCheck" value="PANTALLA"> Pantalla</label><label><input type="checkbox" class="svDoseCheck" value="MICROFONO"> Micrófono/protector</label><label><input type="checkbox" class="svDoseCheck" value="BATERIA"> Batería</label><label><input type="checkbox" class="svDoseCheck" value="REGISTRO"> Registro de medición</label><label><input type="checkbox" class="svDoseCheck" value="SIN_ERROR"> Sin mensajes de error</label></div></div></div><div class="info-banner" id="svDoseTrend"><b>IA de deriva:</b> se comparará esta verificación con el historial interno del mismo equipo.</div></div>`:''}
 ${p==='VIBRATION'?`<div class="derived-box" style="margin-top:14px"><b>📳 Verificación específica de vibrómetro HAV/WBV</b><p>La evaluación usa diferencia porcentual respecto al valor nominal del calibrador. Criterio inteligente: ≤ 5 %.</p><div class="form-grid"><div class="field"><label>Modo / cadena evaluada</label><select id="svVibMode" class="control"><option value="HAV">HAV · Mano-brazo</option><option value="WBV">WBV · Cuerpo entero</option></select></div><div class="field"><label>Sensor / acelerómetro</label><select id="svVibSensor" class="control"><option value="SV105">SV105 · HAV</option><option value="SV38V">SV38V · WBV</option></select></div><div class="field"><label>Frecuencia nominal del calibrador</label><input id="svVibFrequency" class="control" inputmode="decimal" placeholder="Según certificado"><small>Hz</small></div><div class="field"><label>Vigencia del patrón</label><select id="svVibPatternStatus" class="control"><option value="">Seleccione…</option><option>VIGENTE</option><option>NO VIGENTE</option></select></div><div class="field span-3"><label>Comprobación funcional</label><div class="check-grid"><label><input type="checkbox" class="svVibCheck" value="ENCENDIDO"> Encendido/pantalla</label><label><input type="checkbox" class="svVibCheck" value="SENSOR"> Sensor íntegro</label><label><input type="checkbox" class="svVibCheck" value="CABLES"> Cables/conectores</label><label><input type="checkbox" class="svVibCheck" value="BATERIA"> Batería</label><label><input type="checkbox" class="svVibCheck" value="REGISTRO"> Registro/lectura estable</label><label><input type="checkbox" class="svVibCheck" value="SIN_ERROR"> Sin mensajes de error</label></div></div></div><div class="info-banner" id="svVibTrend"><b>IA:</b> comparará la diferencia porcentual actual con el criterio del 5 % y el historial del equipo.</div></div>`:''}
 <h3 class="view-title">Puntos / lecturas desde la ficha</h3><div class="table-wrap"><table class="met-table"><thead><tr><th>Punto / setpoint</th><th>${esc(lab.ref)}</th><th>${esc(lab.ind)}</th><th>Error</th><th>|Error|</th><th>Unidad</th><th></th></tr></thead><tbody id="svRows">${rows}</tbody></table></div><button type="button" class="btn btn-secondary" id="addVerifyRow">＋ Agregar punto</button>
 <div class="info-banner" id="svAiDecision"><b>🤖 Evaluación IA:</b> ingrese las lecturas. El sistema compara |error| contra el límite de aceptación y, si está definido, contra el límite de acreditación. La decisión final continúa bajo confirmación del analista.</div>
 <div class="form-grid" style="margin-top:14px"><div class="field"><label>Decisión final *</label><select id="svResult" class="control"><option value="">Seleccione al concluir…</option><option>CONFORME</option><option>VIGILANCIA</option><option>NO CONFORME</option></select></div><div class="field"><label>Sugerencia IA</label><div style="display:flex;gap:8px"><input id="svSuggestion" class="control" readonly placeholder="Pendiente de datos"><button type="button" class="icon-btn" id="applySvSuggestion">Aplicar</button></div></div><div class="field"><label>Intervalo IA (meses)</label><input id="svIntervalMonths" type="number" min="1" max="12" class="control" readonly value="${esc(i.frequency||((p==='DOSIMETER')?6:''))}"><small>Se recalcula con resultado, error, criterio e histórico.</small></div><div class="field"><label>Próxima fecha IA</label><input id="svNext" type="date" class="control" readonly value="${esc(addMonthsIso(today,Number(i.frequency)||((p==='DOSIMETER')?6:6)))}"></div><div class="field span-2"><label>Fundamento IA del intervalo</label><textarea id="svIntervalReason" class="control" readonly>Esperando lecturas para confirmar el intervalo.</textarea></div><div class="field span-3"><label>Observación breve</label><textarea id="svNotes" class="control" placeholder="Solo si existe algo relevante para la trazabilidad."></textarea></div></div>
 <div class="info-banner"><b>Control técnico:</b> Error = Indicación − Referencia. La sugerencia IA es apoyo verificable; la decisión final y la validez del criterio permanecen bajo responsabilidad del analista.</div>
 <div class="derived-box" style="margin-top:14px"><b>Firma digital P12/PFX <span class="optional-tag">Opcional</span></b><p>Puede archivar la verificación sin firma y completarla después, o firmarla criptográficamente. La firma P12 está autorizada exclusivamente al Coordinador de Calidad <b>JIPSON FRANCO</b>.</p><div class="form-grid"><div class="field span-2"><label>Certificado .p12 / .pfx</label><input id="svP12File" class="control" type="file" accept=".p12,.pfx,application/x-pkcs12"></div><div class="field"><label>Contraseña</label><input id="svP12Pass" class="control" type="password" autocomplete="new-password"></div><div class="field span-2"><label>Motivo de firma</label><input id="svSignReason" class="control" value="Aprobación de verificación interna ${esc(e.code)}"></div></div></div>
 <div id="svMsg" class="form-msg"></div></div><div class="modal-foot"><button class="btn btn-secondary" id="cancelSmartVerify">Cancelar</button><button class="btn btn-secondary" id="saveSmartVerify">Generar y archivar</button><button class="btn btn-primary" id="signSmartVerify">Firmar P12 y archivar</button></div></div></div>`);
 const close=()=>smartVerifyModal.remove();closeSmartVerify.onclick=close;cancelSmartVerify.onclick=close;
 addSvAnalyst.onclick=async()=>{const v=prompt('Nombre del nuevo analista:');if(!v)return;try{await addCatalogItem('verificationAnalysts',v,currentUser);const o=document.createElement('option');o.value=v.trim();o.textContent=v.trim();o.selected=true;svAnalyst.appendChild(o)}catch(err){svMsg.textContent=err.message||String(err);svMsg.classList.add('bad')}};
 addSvPattern.onclick=async()=>{const c=prompt('Código del patrón/referencia:');if(!c)return;const n=prompt('Nombre del patrón/referencia:');if(!n)return;const item=`${c.trim()} | ${n.trim()}`;try{await addCatalogItem('metrologyPatterns',item,currentUser);svReferenceCode.value=c.trim();svReference.value=n.trim();const o=document.createElement('option');o.value=item;svPatternList.appendChild(o)}catch(err){svMsg.textContent=err.message||String(err);svMsg.classList.add('bad')}};
 const readRows=()=>[...document.querySelectorAll('#svRows .verify-row')].map(r=>({setpoint:r.querySelector('.vrSet')?.value.trim()||'',reference:r.querySelector('.vrRef').value.trim(),indicated:r.querySelector('.vrInd').value.trim(),error:r.querySelector('.vrErr').value.trim(),absoluteError:r.querySelector('.vrAbsErr')?.value.trim()||'',unit:r.querySelector('.vrUnit').value.trim()})).filter(r=>r.reference||r.indicated||r.setpoint);
 const updateAi=()=>{
  const rr=readRows(),sug=p==='VIBRATION'?suggestVibrationVerificationDecision(rr):suggestVerificationDecision(rr,svCriterion.value,svAccreditation.value);let decision=sug.decision||'',reason=sug.reason||'';
  const patternStatus=p==='VIBRATION'?(document.getElementById('svVibPatternStatus')?.value||''):(document.getElementById('svPatternStatus')?.value||'');
  if(p==='VIBRATION'&&patternStatus==='NO VIGENTE'){decision='NO CONFORME';reason='Calibrador de vibraciones no vigente. No liberar la verificación hasta repetirla con patrón vigente.';}
  if(p==='VIBRATION'&&Number.isFinite(Number(sug.maxError))){const hist=dossier.filter(d=>d.equipmentId===e.id&&d.category==='VERIFICACION_INTERNA'&&d.generatedData?.profile==='VIBRATION').sort((a,b)=>String(b.issueDate||'').localeCompare(String(a.issueDate||'')));const prev=hist[0]?.generatedData?.aiMaxError;const cur=Number(sug.maxError);if(decision==='CONFORME'&&cur>=3.75){decision='VIGILANCIA';reason+=` Utilización del criterio ${(cur/5*100).toFixed(0)}%: vigilancia.`;}document.getElementById('svVibTrend')&&(document.getElementById('svVibTrend').innerHTML=`<b>IA:</b> diferencia actual ${cur.toFixed(2)} % · criterio ≤ 5 %${Number.isFinite(Number(prev))?` · anterior ${Number(prev).toFixed(2)} %`:''}.`);}
  if(p==='DOSIMETER'){
   const complete=rr.filter(r=>r.reference&&r.indicated&&r.error!=='');
   if(!complete.length){decision='';reason='PENDIENTE DE EVALUACIÓN — ingrese la lectura del dosímetro.'}
   else if(patternStatus==='NO VIGENTE'){decision='NO CONFORME';reason='Patrón/calibrador acústico no vigente. No liberar la verificación hasta usar un patrón vigente.'}
   else{
    const hist=dossier.filter(d=>d.equipmentId===e.id&&d.category==='VERIFICACION_INTERNA'&&d.generatedData?.profile==='DOSIMETER').sort((a,b)=>String(b.issueDate||'').localeCompare(String(a.issueDate||'')));
    const prev=hist[0]?.generatedData?.aiMaxError;const cur=sug.maxError;
    if(Number.isFinite(Number(prev))&&Number.isFinite(Number(cur))){
     const delta=Number(cur)-Number(prev);const tol=sug.tolerance;
     if(decision==='CONFORME'&&Number.isFinite(tol)&&cur/tol>=0.75){decision='VIGILANCIA';reason+=` Utilización del criterio ${(cur/tol*100).toFixed(0)}%: vigilancia.`}
     else if(decision==='CONFORME'&&delta>0&&Number.isFinite(tol)&&delta/tol>=0.25){decision='VIGILANCIA';reason+=` Deriva creciente frente a la verificación anterior (Δ|error|=${delta.toFixed(3)} dB).`}
     document.getElementById('svDoseTrend')&&(document.getElementById('svDoseTrend').innerHTML=`<b>IA de deriva:</b> histórico comparable ${hist.length} · último |error| ${Number(prev).toFixed(3)} dB · actual ${Number(cur).toFixed(3)} dB · Δ ${delta.toFixed(3)} dB.`)
    }
   }
  }
  svSuggestion.value=decision;
  const interval=verificationIntervalAi(e,p,{date:svDate.value,decision,maxError:sug.maxError,tolerance:sug.tolerance,patternStatus,configuredMonths:i.frequency});
  svIntervalMonths.value=interval.months||'';svNext.value=interval.nextDate||'';svIntervalReason.value=interval.reason||'';
  const acc=sug.accreditationStatus?` <b>Acreditación:</b> ${esc(sug.accreditationStatus)}.`:'';
  svAiDecision.innerHTML=`<b>🤖 Evaluación IA:</b> ${esc(decision?`Sugerencia ${decision}. ${reason}`:reason)}${acc}${interval.months?` <b>Próxima verificación IA:</b> ${esc(interval.months)} mes(es) · ${esc(dateTxt(interval.nextDate))}.`:''} <b>La selección final no se cambia automáticamente.</b>`;
 };
 const bind=()=>document.querySelectorAll('#svRows .verify-row').forEach(r=>{const calc=()=>{const a=parseFloat(r.querySelector('.vrRef').value.replace(',','.')),b=parseFloat(r.querySelector('.vrInd').value.replace(',','.'));const err=Number.isFinite(a)&&Number.isFinite(b)?b-a:NaN;r.querySelector('.vrErr').value=Number.isFinite(err)?err.toFixed(4).replace(/\.?0+$/,''):'';r.querySelector('.vrAbsErr').value=Number.isFinite(err)?Math.abs(err).toFixed(4).replace(/\.?0+$/,''):'';updateAi()};r.querySelector('.vrRef').oninput=calc;r.querySelector('.vrInd').oninput=calc;r.querySelector('.vrDel').onclick=()=>{if(document.querySelectorAll('#svRows .verify-row').length>1){r.remove();updateAi()}}});bind();
 addVerifyRow.onclick=()=>{svRows.insertAdjacentHTML('beforeend',rowHtml(''));bind()};svCriterion.oninput=updateAi;svAccreditation.oninput=updateAi;document.getElementById('svPatternStatus')?.addEventListener('change',updateAi);document.getElementById('svVibPatternStatus')?.addEventListener('change',updateAi);applySvSuggestion.onclick=()=>{if(svSuggestion.value){svResult.value=svSuggestion.value;updateAi()}};svResult.onchange=updateAi;
 svDate.onchange=()=>{svCode.value=verificationSequence(e,svDate.value);updateAi()};
 const persistVerification=async(sign=false)=>{
  const rows=readRows();
  if(!svDate.value||!svAnalyst.value||!svReferenceCode.value.trim()||!svReference.value.trim()||!svCriterion.value.trim()||!rows.some(r=>r.reference&&r.indicated)||!svResult.value||(p==='DOSIMETER'&&!document.getElementById('svPatternStatus')?.value)||(p==='VIBRATION'&&!document.getElementById('svVibPatternStatus')?.value)){svMsg.textContent='Complete fecha, analista, patrón/referencia, criterio, al menos una lectura completa, decisión final y la vigencia del patrón cuando aplique (dosímetro/vibrómetro).';svMsg.classList.add('bad');return}
  const p12=svP12File.files[0],password=svP12Pass.value;
  if(sign&&!isQualityCoordinator()){svMsg.textContent='Firma no autorizada. Solo el Coordinador de Calidad JIPSON FRANCO puede firmar verificaciones con P12/PFX.';svMsg.classList.add('bad');return}
  if(sign&&(!p12||!password)){svMsg.textContent='Para firmar seleccione el certificado P12/PFX e ingrese la contraseña.';svMsg.classList.add('bad');return}
  saveSmartVerify.disabled=true;signSmartVerify.disabled=true;svMsg.classList.remove('bad');svMsg.textContent=sign?'Generando registro estructurado y aplicando firma P12…':'Generando registro estructurado y actualizando trazabilidad…';
  try{
   const ai=p==='VIBRATION'?suggestVibrationVerificationDecision(rows):suggestVerificationDecision(rows,svCriterion.value,svAccreditation.value);
   const baseData={verificationCode:svCode.value,date:svDate.value,nextDate:svNext.value,verificationIntervalMonths:Number(svIntervalMonths.value)||0,verificationIntervalReason:svIntervalReason.value.trim(),analyst:svAnalyst.value,reference:svReference.value.trim(),referenceCode:svReferenceCode.value.trim(),criterion:svCriterion.value.trim(),accreditationLimit:svAccreditation.value.trim(),result:svResult.value,aiSuggestion:ai.decision,aiReason:ai.reason,aiMaxError:ai.maxError,accreditationStatus:ai.accreditationStatus,notes:svNotes.value.trim(),profile:p,rows,strategy:i.strategy||'',pointsCount:rows.length,uvParameter:e.plans?.verification?.uvParameter||'',dosimeter:p==='DOSIMETER'?{frequencyHz:document.getElementById('svDoseFrequency')?.value||'',nominalDb:document.getElementById('svDoseNominal')?.value||'',patternStatus:document.getElementById('svPatternStatus')?.value||'',functionalChecks:[...document.querySelectorAll('.svDoseCheck:checked')].map(x=>x.value)}:null,vibration:p==='VIBRATION'?{mode:document.getElementById('svVibMode')?.value||'',sensor:document.getElementById('svVibSensor')?.value||'',frequencyHz:document.getElementById('svVibFrequency')?.value||'',patternStatus:document.getElementById('svVibPatternStatus')?.value||'',functionalChecks:[...document.querySelectorAll('.svVibCheck:checked')].map(x=>x.value)}:null,supervisor:'JIPSON FRANCO'};
   let blob=await buildVerificationPdf(i,baseData),signature={signed:false};
   if(sign){
    signature={signed:true,method:'P12/PFX',signedBy:'JIPSON FRANCO',signedByEmail:currentUser?.email||'',signedAt:new Date().toISOString(),sha256:'',reason:svSignReason.value.trim()};
    const visual=await buildVerificationPdf(i,{...baseData,signature});
    const signedFinal=await signGeneratedPdfBlob(visual,{p12,password,reason:svSignReason.value.trim(),name:'JIPSON FRANCO',equipmentCode:e.code,documentCode:baseData.verificationCode});
    blob=signedFinal.blob;signature.sha256=signedFinal.hash||'';
   }
   const prior=dossier.filter(d=>d.equipmentId===e.id&&d.category==='VERIFICACION_INTERNA');
   const rev=String(Math.max(0,...prior.map(d=>parseInt(String(d.revision||'0').replace(/\D/g,''),10)||0))+1).padStart(2,'0');
   const generatedData={...baseData,internal:true,type:'VERIFICATION',equipmentProfile:p,signature};
   const metadata={equipmentId:e.id,equipmentCode:e.code,equipmentName:e.name,category:'VERIFICACION_INTERNA',title:`${baseData.verificationCode} · Verificación interna ${e.code}${sign?' · FIRMADO P12':''}`,revision:rev,issueDate:svDate.value,expiryDate:svNext.value,notes:svNotes.value.trim(),generatedData,signature};
   const docId=await addGeneratedDossierDocument(metadata,blob,`${baseData.verificationCode}${sign?'_FIRMADO':''}.pdf`,currentUser);
   await archiveCategoryRevisions(e.id,'VERIFICACION_INTERNA',docId,'Nueva verificación interna',currentUser);
   if(baseData.verificationIntervalMonths>0){
    await updateEquipment(e.id,{plans:{verification:{internal:{frequencyMonths:baseData.verificationIntervalMonths,responsible:e?.plans?.verification?.internal?.responsible||svAnalyst.value}}}},currentUser);
   }
   await updateEquipmentCurrentControl(e.id,'VERIFICATION',{lastDate:svDate.value,nextDate:svNext.value,result:svResult.value,sourceRecordId:docId,source:'VERIFICACION_INTERNA',analyst:svAnalyst.value,verificationCode:baseData.verificationCode,verificationIntervalMonths:baseData.verificationIntervalMonths,approvedInterval:baseData.verificationIntervalMonths,intervalReason:baseData.verificationIntervalReason},currentUser,'INTERNAL');
   {const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${baseData.verificationCode}${sign?'_FIRMADO':''}.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),4000)}
   close();currentPage='verificationInternal';renderApp();showGlobalToast(sign?'Verificación firmada P12 y archivada correctamente.':'Verificación generada y archivada correctamente.','ok');
  }catch(err){svMsg.textContent=err.message||String(err);svMsg.classList.add('bad')}
  finally{saveSmartVerify.disabled=false;signSmartVerify.disabled=false;svP12Pass.value=''}
 };
 saveSmartVerify.onclick=()=>persistVerification(false);
 signSmartVerify.onclick=()=>persistVerification(true);
 updateAi();
}


function calibrationMethodSlug(name=''){return String(name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,18)}
function calibrationSequence(e,date,methodName=''){
 const year=String(date||isoToday()).slice(0,4), prefix=`IC-${e.code}-${year}-`;
 const nums=dossier.filter(d=>d.equipmentId===e.id&&d.category==='CALIBRACION_INTERNA')
  .map(d=>String(d.generatedData?.calibrationCode||''))
  .filter(code=>code.includes(`-${year}-`))
  .map(code=>{const m=code.match(/-(\d{3,})$/);return m?parseInt(m[1],10):0});
 return `${prefix}${String(Math.max(0,...nums)+1).padStart(3,'0')}`;
}
function calibrationProfile(e){
 const chars=e?.metrologicalCharacteristics||[];
 const hay=[e?.name,e?.technical?.methodPrinciple,...chars.flatMap(x=>[x.magnitude,x.unit])].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 if(/pq200|material particulado|captador|particulate sampler|pm10|pm2\.5|flujo.*l\/min|caudal/.test(hay))return 'CAPTADOR_MP';
 if(/masa|balanza|peso|gram/.test(hay))return 'MASS';
 if(/temperatura|termometro|estufa|incubadora|horno|bano|plato calentador/.test(hay))return 'TEMPERATURE';
 if(/medidor de cloro|cloro residual|cloro total|pocket colorimeter|colorimetro.*cloro|hach 8021|hach 8167/.test(hay))return 'CHLORINE';
 if(/uv|visible|espectro|absorbancia/.test(hay))return 'UV_VISIBLE';
 if(/oxigeno disuelto|oxigenometro|medidor de od|\bod\b/.test(hay))return 'OD';
 if(/ph|potencial de hidrogeno/.test(hay))return 'PH';
 if(/conduct/.test(hay))return 'CONDUCTIVITY';
 if(/volumen|pipeta|bureta|matraz/.test(hay))return 'VOLUME';
 return 'GENERIC';
}
function calibrationProfileName(p){return ({MASS:'Masa / balanza',TEMPERATURE:'Temperatura',UV_VISIBLE:'UV-VISIBLE',CHLORINE:'Colorímetro / Cloro',PH:'pH',OD:'Oxígeno disuelto (OD)',CONDUCTIVITY:'Conductividad',VOLUME:'Volumen',CAPTADOR_MP:'Captador MP / Caudal',GENERIC:'Calibración general'})[p]||'Calibración general'}
function internalCalibrationItems(){return buildProgramItems().filter(i=>i.type==='CALIBRATION'&&i.modality==='INTERNAL')}
function calibrationConfiguredPoints(e){
 const chars=e?.metrologicalCharacteristics||[];
 const pts=chars.flatMap(c=>String(c.controlPoints||'').split(/[,;\n]|\sy\s/i).map(x=>x.trim()).filter(Boolean));
 return [...new Set(pts)];
}
function calibrationDefaultCriterion(e){
 const chars=e?.metrologicalCharacteristics||[];
 return chars.map(x=>x.acceptanceCriterion).find(Boolean)||chars.map(x=>x.empCriterion||x.accuracyEmp).find(Boolean)||'Definir criterio de conformidad según ficha técnica, procedimiento o EMP vigente.';
}
function latestInternalCalibrationDocument(i){
 const scope=String(i?.scopeKey||'');
 const rows=dossier.filter(d=>d.equipmentId===i?.equipment?.id&&d.category==='CALIBRACION_INTERNA'&&String(d.scopeKey||d.generatedData?.scopeKey||'')===scope&&d.status==='VIGENTE');
 const rank=d=>{const r=parseInt(String(d.revision||'0').replace(/\D/g,''),10)||0;const t=d.updatedAt?.toMillis?.()||d.createdAt?.toMillis?.()||((d.updatedAt?.seconds||d.createdAt?.seconds||0)*1000)||0;return r*1e13+t};
 return rows.sort((a,b)=>rank(b)-rank(a))[0]||null;
}
function calibrationDocumentSigned(d){return !!(d?.signature?.signed||d?.generatedData?.signature?.signed)}
function isCovPidOriginalDocument(d){
 return !!(d?.generatedData?.pdfOriginal && String(d?.generatedData?.profile||'').startsWith('DETECTOR_COV_PID'));
}
function covPidDocumentInfo(d){
 const x=d.generatedData||{};
 const e=equipment.find(v=>v.id===d.equipmentId);
 document.getElementById('covPdfInfoModal')?.remove();
 document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop open" id="covPdfInfoModal"><div class="modal"><div class="modal-head"><div><h2>Calibración COV/PID · ${esc(d.equipmentCode||e?.code||'')}</h2><p>PDF original archivado · consulta sin nueva carga</p></div><button class="close-btn" id="covInfoClose">×</button></div><div class="modal-body"><div class="info-banner"><b>PDF ORIGINAL ARCHIVADO.</b> El documento permanece inalterado; no requiere generar un segundo informe. La autorización del PDF original se verifica según el procedimiento del laboratorio.</div><div class="form-grid"><div class="field"><label>Registro</label><input class="control" readonly value="${esc(x.calibrationCode||'')}"></div><div class="field"><label>Fecha de calibración</label><input class="control" readonly value="${esc(dateTxt(x.date||d.issueDate))}"></div><div class="field"><label>Próxima calibración</label><input class="control" readonly value="${esc(dateTxt(x.nextDate||d.expiryDate))}"></div><div class="field"><label>Responsable</label><input class="control" readonly value="${esc(x.analyst||'')}"></div><div class="field"><label>Resultado documentado</label><input class="control" readonly value="${esc(x.result||'')}"></div><div class="field"><label>Certificado</label><input class="control" readonly value="${esc(x.referenceCertificate||'')}"></div><div class="field span-3"><label>Archivo original</label><input class="control" readonly value="${esc(x.originalFilename||d.fileName||'')}"></div><div class="field span-3"><label>Observaciones</label><textarea class="control" readonly>${esc(x.notes||'')}</textarea></div></div></div><div class="modal-foot"><button class="btn btn-secondary" id="covInfoClose2">Cerrar</button><button class="btn btn-secondary" id="covInfoDownload">Descargar PDF</button><button class="btn btn-primary" id="covInfoView">Ver PDF original</button></div></div></div>`);
 const close=()=>document.getElementById('covPdfInfoModal')?.remove();
 document.getElementById('covInfoClose').onclick=close;
 document.getElementById('covInfoClose2').onclick=close;
 document.getElementById('covInfoDownload').onclick=()=>openArchivedDocument(d.id,false);
 document.getElementById('covInfoView').onclick=()=>openArchivedDocument(d.id,true);
}
function calibrationActionHtml(i){
 const d=latestInternalCalibrationDocument(i),isSmart=['CURVA_UV','CONDUCTIVITY','OD','PH_CURVE'].includes(i?.calibrationMethod?.profile);
 if(!d)return `<button class="icon-btn smartCal" data-task="${i.id}">Ejecutar</button><button class="icon-btn calDossier" data-eqid="${i.equipment.id}">Expediente</button>`;
 if(isCovPidOriginalDocument(d))return `<button class="icon-btn covInfo" data-doc="${d.id}">Ver registro</button><button class="icon-btn covView" data-doc="${d.id}">Ver PDF</button><button class="icon-btn covDownload" data-doc="${d.id}">Descargar</button><button class="icon-btn smartCal" data-task="${i.id}">Nueva calibración</button><button class="icon-btn calDossier" data-eqid="${i.equipment.id}">Expediente</button>`;
 const signed=calibrationDocumentSigned(d);
 if(!signed&&isSmart)return `<button class="icon-btn editCal" data-task="${i.id}" data-doc="${d.id}">Editar</button><button class="icon-btn signCal" data-task="${i.id}" data-doc="${d.id}">Firmar P12</button><button class="icon-btn calDossier" data-eqid="${i.equipment.id}">Expediente</button>`;
 if(signed){const canNew=['VENCIDA','HOY','PROXIMA'].includes(i.status);return `${canNew?`<button class="icon-btn smartCal" data-task="${i.id}">Nueva calibración</button>`:'<span class="program-state program-ok" title="Documento firmado: no admite edición">FIRMADO · BLOQUEADO</span>'}<button class="icon-btn calDossier" data-eqid="${i.equipment.id}">Expediente</button>`}
 return `<button class="icon-btn smartCal" data-task="${i.id}">Ejecutar</button><button class="icon-btn calDossier" data-eqid="${i.equipment.id}">Expediente</button>`;
}
function calibrationSignatureStateHtml(i){
 const d=latestInternalCalibrationDocument(i);if(!d)return '';
 if(isCovPidOriginalDocument(d))return '<small style="font-weight:800;color:#067647">PDF ORIGINAL ARCHIVADO · sin informe duplicado</small>';
 return calibrationDocumentSigned(d)?'<small>Firma P12: FIRMADO · documento bloqueado</small>':'<small style="font-weight:800;color:#9a5b00">PENDIENTE DE FIRMA P12 · puede editar o firmar</small>';
}
function renderCalibrationInternal(){
 const all=internalCalibrationItems();
 const withEvidence=all.filter(i=>i.evidence).length,pending=all.filter(i=>!i.evidence).length,due=all.filter(i=>['VENCIDA','HOY','PROXIMA'].includes(i.status)).length;
 const content=`<section class="content verification-page"><div class="module-title"><div><h1>Calibración Interna Inteligente</h1><p>Registro técnico por equipo, preparado desde ahora para deriva, incertidumbre y evaluación futura de intervalos.</p></div></div>
 <div class="kpis"><div class="kpi"><strong>${all.length}</strong><span>Calibraciones internas configuradas</span></div><div class="kpi"><strong>${withEvidence}</strong><span>Con calibración vigente</span></div><div class="kpi kpi-warning"><strong>${pending}</strong><span>Sin ejecución</span></div><div class="kpi kpi-danger"><strong>${due}</strong><span>Vencidas / próximas</span></div></div>
 <div class="program-ai"><div class="program-ai-head"><div><b>🤖 Copiloto de calibración</b><span>Precarga datos del equipo, puntos configurados y criterio. Calcula promedio, error y corrección; deja reservados deriva, incertidumbre e intervalo para las siguientes etapas.</span></div></div><div class="program-ai-grid">${all.map((i,n)=>`<button class="program-ai-card smartCal" data-task="${i.id}"><span>${n+1}</span><div><b>${esc(i.equipment.code)} · ${esc(i.equipment.name)}${i.methodName?` · ${esc(i.methodName)}`:''}</b><small>${i.calibrationMethod?.profile==='CURVA_UV'?'Curva UV-VISIBLE':i.calibrationMethod?.profile==='CONDUCTIVITY'?'Conductividad inteligente':i.calibrationMethod?.profile==='OD'?'Oxígeno disuelto inteligente':i.calibrationMethod?.profile==='PH_CURVE'?'Curva pH inteligente':esc(calibrationProfileName(calibrationProfile(i.equipment)))} · ${i.evidence?'Última '+dateTxt(i.lastDate):'Sin calibración registrada'} · ${esc(i.status.replace('_',' '))}</small></div><strong>Ejecutar →</strong></button>`).join('')||'<div class="ok-item">No hay calibraciones internas configuradas en Inventario.</div>'}</div></div>
 <div class="panel"><div class="table-wrap"><table class="program-table"><thead><tr><th>Equipo</th><th>Método / perfil</th><th>Frecuencia</th><th>Última</th><th>Próxima</th><th>Estado</th><th>Responsable</th><th>Acciones</th></tr></thead><tbody>${all.map(i=>`<tr><td><b class="code">${esc(i.equipment.code)}</b><small>${esc(i.equipment.name)} · ${esc(i.equipment.location||'')}</small></td><td><b>${i.methodName?esc(i.methodName):esc(calibrationProfileName(calibrationProfile(i.equipment)))}</b><small>${i.calibrationMethod?.profile==='CURVA_UV'?'Curva UV-VISIBLE · informe técnico inteligente':i.calibrationMethod?.profile==='CONDUCTIVITY'?'Conductividad · incertidumbre, EMP y regla de decisión':i.calibrationMethod?.profile==='OD'?'OD · titulación de referencia, incertidumbre y regla de decisión':i.calibrationMethod?.profile==='PH_CURVE'?'pH · 3 puntos, incertidumbre, regla de decisión e intervalo IA':(i.equipment.metrologicalCharacteristics||[]).length+' característica(s) metrológica(s)'}</small>${calibrationSignatureStateHtml(i)}</td><td>${i.frequency?i.frequency+' meses':'Sin frecuencia'}</td><td>${i.lastDate?dateTxt(i.lastDate):'<span class="doc-missing">SIN EJECUCIÓN</span>'}</td><td>${i.dueDate?dateTxt(i.dueDate):'<span class="doc-missing">SIN FECHA</span>'}</td><td>${programStatusBadge(i.status)}</td><td>${esc(i.who||'Por definir')}</td><td><div class="row-actions">${calibrationActionHtml(i)}</div></td></tr>`).join('')||'<tr><td colspan="8" class="empty-row">Configure Calibración Interna desde Inventario Maestro.</td></tr>'}</tbody></table></div></div>
 <div class="info-banner"><b>Flujo:</b> Inventario → Programa Metrológico → Calibración Interna → PDF / firma P12 → Expediente → Inventario actualiza Última/Próxima → Programa recalcula. <b>Firma inteligente:</b> los informes generados siguen su flujo P12. Para COV/PID, el PDF original se archiva y consulta sin crear un segundo informe ni exigir otra carga.</div></section>`;
 shell(content,'Calibración Interna','Ejecución técnica · preparada para deriva, incertidumbre e intervalos');
 document.querySelectorAll('.smartCal').forEach(b=>b.onclick=()=>{const i=all.find(x=>x.id===b.dataset.task);if(i)openInternalCalibration(i)});
 document.querySelectorAll('.editCal').forEach(b=>b.onclick=()=>{const i=all.find(x=>x.id===b.dataset.task),d=dossier.find(x=>x.id===b.dataset.doc);if(i&&d)openInternalCalibration(i,{document:d,mode:'edit'})});
 document.querySelectorAll('.signCal').forEach(b=>b.onclick=()=>{const i=all.find(x=>x.id===b.dataset.task),d=dossier.find(x=>x.id===b.dataset.doc);if(i&&d)openInternalCalibration(i,{document:d,mode:'sign'})});
 document.querySelectorAll('.covInfo').forEach(b=>b.onclick=()=>{const d=dossier.find(x=>x.id===b.dataset.doc);if(d)covPidDocumentInfo(d)});
 document.querySelectorAll('.covView').forEach(b=>b.onclick=()=>openArchivedDocument(b.dataset.doc,true));
 document.querySelectorAll('.covDownload').forEach(b=>b.onclick=()=>openArchivedDocument(b.dataset.doc,false));
 document.querySelectorAll('.calDossier').forEach(b=>b.onclick=()=>{currentPage='dossier';filters.dq=equipment.find(e=>e.id===b.dataset.eqid)?.code||'';renderApp()});
}
async function buildCalibrationPdf(i,data){
 const e=i.equipment,pdf=await PDFDocument.create(),font=await pdf.embedFont(StandardFonts.Helvetica),bold=await pdf.embedFont(StandardFonts.HelveticaBold);
 const blue=rgb(.10,.36,.60),light=rgb(.90,.95,.985),dark=rgb(.10,.16,.24),gray=rgb(.36,.42,.49),line=rgb(.70,.76,.82);
 let logo=null;try{logo=await pdf.embedJpg(await fetch(new URL('/psi-logo.jpeg',window.location.origin)).then(r=>r.arrayBuffer()))}catch(_){}
 let page,y,pageNo=0;
 const wrap=(v,w,sz=8,f=font)=>{const words=safePdfString(v).split(/\s+/).filter(Boolean),out=[];let cur='';for(const q of words){const t=cur?cur+' '+q:q;if(cur&&f.widthOfTextAtSize(t,sz)>w){out.push(cur);cur=q}else cur=t}if(cur)out.push(cur);return out.length?out:['']};
 const addPage=()=>{page=pdf.addPage([595.28,841.89]);pageNo++;y=728;const hx=36,hy=758,hw=523,hh=60,lw=78,rw=132,cx=hx+lw,rx=hx+hw-rw;page.drawRectangle({x:hx,y:hy,width:hw,height:hh,borderColor:blue,borderWidth:1});page.drawLine({start:{x:cx,y:hy},end:{x:cx,y:hy+hh},thickness:.6,color:line});page.drawLine({start:{x:rx,y:hy},end:{x:rx,y:hy+hh},thickness:.6,color:line});if(logo){const d=logo.scale(1),sc=Math.min(62/d.width,38/d.height),w=d.width*sc,h=d.height*sc;page.drawImage(logo,{x:hx+(lw-w)/2,y:hy+(hh-h)/2,width:w,height:h})}const centerW=rx-cx,ct=(t,yy,sz,col=dark)=>{t=safePdfString(t);page.drawText(t,{x:cx+(centerW-bold.widthOfTextAtSize(t,sz))/2,y:yy,size:sz,font:bold,color:col})};ct('LABORATORIO DE ANALISIS AMBIENTAL DE',hy+41,8.5);ct('PRODUCTOS Y SERVICIOS INDUSTRIALES C. LTDA',hy+29,8.5);ct('Registro de Calibracion Interna',hy+12,10.2,blue);page.drawText('Registro N°',{x:rx+12,y:hy+40,size:7,font:bold,color:gray});wrap(data.calibrationCode,rw-24,7.3,bold).slice(0,2).forEach((ln,k)=>page.drawText(ln,{x:rx+12,y:hy+28-k*9,size:7.3,font:bold,color:dark}));page.drawText(`Pagina ${pageNo}`,{x:rx+rw-54,y:hy+6,size:6.7,font,color:gray})};
 const ensure=(h=60)=>{if(y<h+52)addPage()};
 const title=t=>{ensure(34);page.drawText(safePdfString(t),{x:40,y,size:11,font:bold,color:blue});page.drawLine({start:{x:40,y:y-4},end:{x:555,y:y-4},thickness:1,color:blue});y-=22};
 const kv=(a,b)=>{ensure(22);page.drawText(safePdfString(a),{x:44,y,size:7.5,font:bold,color:gray});wrap(b,360,8).slice(0,2).forEach((ln,k)=>page.drawText(ln,{x:180,y:y-k*10,size:8,font,color:dark}));y-=20};
 addPage();title('1. IDENTIFICACION DEL EQUIPO');[['Equipo',`${e.code} - ${e.name}`],['Serie / P/N',e.technical?.serialNumber||'-'],['Marca / Modelo',[e.technical?.brand,e.technical?.model].filter(Boolean).join(' / ')||'-'],['Ubicacion',e.location||'-'],['Responsable',e.responsible||'-']].forEach(x=>kv(...x));
 title('2. DATOS DE LA CALIBRACION');[['Fecha',dateTxt(data.date)],['Analista',data.analyst],['Metodo / parametro',data.calibrationMethod||'Calibracion general'],['Perfil',data.calibrationMethod?((i.calibrationMethod?.profile==='CURVA_UV')?'Curva UV-VISIBLE - formato individual pendiente':calibrationProfileName(data.profile)):calibrationProfileName(data.profile)],['Condiciones ambientales',`Temperatura: ${data.ambientTemp||'-'} | Humedad: ${data.ambientRh||'-'}`],['Proxima calibracion',dateTxt(data.nextDate)],['Referencias tecnicas',data.criteriaReferences||'—'],['Regla de decision',data.decisionRule||'—']].forEach(x=>kv(...x));
 title('3. PATRON / REFERENCIA');[['Codigo',data.referenceCode],['Patron / referencia',data.reference],['Certificado / vigencia',data.referenceCertificate||'-']].forEach(x=>kv(...x));
 title('4. RESULTADOS');ensure(52);const cols=[40,126,202,278,354,430,500,555],heads=['Punto','Referencia','Lectura 1','Lectura 2','Lectura 3','Promedio','Error'];page.drawRectangle({x:40,y:y-18,width:515,height:20,color:blue});heads.forEach((h,j)=>page.drawText(h,{x:cols[j]+3,y:y-12,size:6.4,font:bold,color:rgb(1,1,1)}));y-=22;for(const r of data.rows){ensure(25);const vals=[r.point,r.reference,r.read1,r.read2,r.read3,r.mean,r.error];vals.forEach((v,j)=>page.drawText(safePdfString(v||'-').slice(0,16),{x:cols[j]+3,y:y-11,size:6.8,font,color:dark}));page.drawRectangle({x:40,y:y-16,width:515,height:20,borderColor:line,borderWidth:.45});y-=20}
 title('5. EVALUACION');kv('Criterio de aceptacion',data.criterion);kv('Decision final',data.result);kv('Observaciones',data.notes||'-');
 title('6. TRAZABILIDAD FUTURA');kv('Deriva','Reservada para calculo historico posterior');kv('Incertidumbre','Campo preparado; presupuesto se implementara en siguiente etapa');kv('Intervalo','Frecuencia actual conservada; recomendacion futura basada en historial');
 title('7. RESPONSABLES');kv('Analista que calibra',data.analyst);kv('Coordinador de Calidad','JIPSON FRANCO');if(data.signature?.signed)kv('Firma digital','FIRMADO P12/PFX · documento bloqueado');
 return new Blob([await pdf.save()],{type:'application/pdf'});
}
function uvDefaultLevels(methodName=''){
 const k=normalizeKey(methodName);
 if(k.includes('cloro')||k.includes('chlorine'))return [0.15,0.5,1,1.5,2];
 if(k.includes('dqo')&&k.includes('alto'))return [50,100,250,500,1000];
 if(k.includes('dqo'))return [50,100,250,500,1000];
 return [];
}
function uvMethodDefaultProcedure(methodName=''){
 const k=normalizeKey(methodName);
 if(k.includes('cloro')||k.includes('chlorine'))return 'PEE/LAB-PSI/17';
 if(k.includes('dqo'))return 'EPA 410.4 – DQO Colorimétrico (rango 50–1000 mg/L)';
 return methodName||'Procedimiento analítico vigente';
}
function uvFmt(v,d=4){const n=Number(v);return Number.isFinite(n)?n.toFixed(d).replace(/\.0+$/,'').replace(/(\.\d*?)0+$/,'$1'):'—'}
function uvNum(v){const n=parseFloat(String(v??'').replace(',','.'));return Number.isFinite(n)?n:NaN}
function uvReadPrimaryRows(){return [...document.querySelectorAll('#uvPrimaryRows .uv-level-row')].map(r=>({level:r.querySelector('.uv-level')?.value||'',r1:r.querySelector('.uv-r1')?.value||'',r2:r.querySelector('.uv-r2')?.value||'',r3:r.querySelector('.uv-r3')?.value||'',uLimit:r.querySelector('.uv-ulimit')?.value||''})).filter(x=>x.level||x.r1||x.r2||x.r3)}
function uvDistributionKey(v='RECTANGULAR'){
 const s=String(v??'').toUpperCase(); const n=uvNum(v);
 if(Number.isFinite(n)){if(Math.abs(n-Math.sqrt(6))<0.05)return 'TRIANGULAR';if(Math.abs(n-2)<0.05)return 'NORMAL_K2';return 'RECTANGULAR'}
 if(s.includes('TRI'))return 'TRIANGULAR'; if(s.includes('NORMAL'))return 'NORMAL_K2'; return 'RECTANGULAR';
}
function uvDistributionDivisor(v='RECTANGULAR'){const k=uvDistributionKey(v);return k==='TRIANGULAR'?Math.sqrt(6):k==='NORMAL_K2'?2:Math.sqrt(3)}
function uvDistributionLabel(v='RECTANGULAR'){const k=uvDistributionKey(v);return k==='TRIANGULAR'?'Triangular (√6)':k==='NORMAL_K2'?'Normal (k=2)':'Rectangular (√3) · recomendada'}
function uvReadReagentRows(){return [...document.querySelectorAll('#uvReagentRows .uv-reagent-row')].map(r=>({name:r.querySelector('.uv-rname')?.value||'',manufacturer:r.querySelector('.uv-rmfg')?.value||'',lot:r.querySelector('.uv-rlot')?.value||'',expiry:r.querySelector('.uv-rexp')?.value||''})).filter(x=>x.name||x.manufacturer||x.lot||x.expiry)}
function uvReagentRow(v={}){return `<tr class="uv-reagent-row"><td><input class="control uv-rname" value="${esc(v.name||'')}" placeholder="Nombre del reactivo"></td><td><input class="control uv-rmfg" value="${esc(v.manufacturer||'')}" placeholder="Marca / fabricante"></td><td><input class="control uv-rlot" value="${esc(v.lot||'')}" placeholder="Lote"></td><td><input class="control uv-rexp" type="date" value="${esc(v.expiry||'')}"></td><td><button type="button" class="icon-btn uv-rdel">×</button></td></tr>`}
function uvReadVolRows(){return [...document.querySelectorAll('#uvVolRows .uv-vol-row')].map(r=>({material:r.querySelector('.uv-vmat')?.value||'',volume:r.querySelector('.uv-vvol')?.value||'',tolerance:r.querySelector('.uv-vtol')?.value||'',distribution:r.querySelector('.uv-vdist')?.value||'RECTANGULAR',expandedCalibrationU:r.querySelector('.uv-vUcal')?.value||'',calibrationK:r.querySelector('.uv-vkcal')?.value||'2',certificate:r.querySelector('.uv-vcert')?.value||''})).filter(x=>x.material||x.volume)}
function uvVolRow(v={}){const dk=uvDistributionKey(v.distribution||'RECTANGULAR'),div=uvDistributionDivisor(dk),Ucal=v.expandedCalibrationU??v.uCalibration??'',kcal=v.calibrationK??2,d=volumetricUncertaintyDetails(v.tolerance,div,Ucal,kcal,v.volume);return `<tr class="uv-vol-row"><td><input class="control uv-vmat" value="${esc(v.material||'')}"></td><td><input class="control uv-vvol" type="number" step="any" value="${esc(v.volume||'')}"></td><td><input class="control uv-vtol" type="number" step="any" value="${esc(v.tolerance||'')}"></td><td><select class="control uv-vdist"><option value="RECTANGULAR" ${dk==='RECTANGULAR'?'selected':''}>Rectangular (√3) · recomendada</option><option value="TRIANGULAR" ${dk==='TRIANGULAR'?'selected':''}>Triangular (√6)</option><option value="NORMAL_K2" ${dk==='NORMAL_K2'?'selected':''}>Normal (k=2)</option></select></td><td class="uv-vutol">${Number.isFinite(d.uTolerance)?uvFmt(d.uTolerance,6):'—'}</td><td><input class="control uv-vUcal" type="number" step="any" value="${esc(Ucal)}" title="Incertidumbre expandida del certificado"></td><td><input class="control uv-vkcal" type="number" min="0.1" step="any" value="${esc(kcal)}"></td><td class="uv-vucalstd">${Number.isFinite(d.uCalibration)?uvFmt(d.uCalibration,6):'—'}</td><td class="uv-vutotal"><b>${Number.isFinite(d.uV)?uvFmt(d.uV,6):'—'}</b></td><td class="uv-vurel">${Number.isFinite(d.uVRelative)?uvFmt(d.uVRelative,7):'—'}</td><td><input class="control uv-vcert" value="${esc(v.certificate||'')}"></td><td><button type="button" class="icon-btn uv-vdel">×</button></td></tr>`}
function uvMaterialOptions(volRows=[],kind='MATRAZ',selected='',allowNA=false){const rx=kind==='MATRAZ'?/matraz/i:/pipeta/i,rows=volRows.filter(v=>rx.test(v.material||'')&&Number.isFinite(uvNum(v.volume)));let out=allowNA?`<option value="" ${selected===''?'selected':''}>N/A · directo del patrón</option>`:'';out+=rows.map(v=>{const val=String(v.volume),d=volumetricUncertaintyDetails(v.tolerance,uvDistributionDivisor(v.distribution),v.expandedCalibrationU??v.uCalibration,v.calibrationK??2,v.volume);return `<option value="${esc(val)}" ${String(selected)===val?'selected':''}>${esc(v.material)} ${esc(val)} mL · uV=${Number.isFinite(d.uV)?uvFmt(d.uV,6):'pendiente'}</option>`}).join('');return out||'<option value="">Sin material configurado</option>'}
function uvFindVolumetric(volRows=[],kind='MATRAZ',volume=''){const rx=kind==='MATRAZ'?/matraz/i:/pipeta/i,V=uvNum(volume);return volRows.find(v=>rx.test(v.material||'')&&Number.isFinite(V)&&Math.abs(uvNum(v.volume)-V)<1e-9)||null}
function uvPipetteRows(volRows=[]){return volRows.map((v,index)=>({v,index,capacity:uvNum(v.volume),adjustable:/micro\s*pipeta|micropipeta/i.test(v.material||'')})).filter(x=>/pipeta/i.test(x.v.material||'')&&Number.isFinite(x.capacity)&&x.capacity>0).map(x=>{const d=volumetricUncertaintyDetails(x.v.tolerance,uvDistributionDivisor(x.v.distribution),x.v.expandedCalibrationU??x.v.uCalibration,x.v.calibrationK??2,x.v.volume);return {...x,uV:d.uV}}).filter(x=>Number.isFinite(x.uV))}
function uvExpectedAliquot(level,referenceConc,flaskVolume){const c=uvNum(referenceConc),x=uvNum(level),vf=uvNum(flaskVolume);if(!Number.isFinite(c)||c<=0||!Number.isFinite(x)||x<0||!Number.isFinite(vf)||vf<=0)return NaN;return x*vf/c}
function uvPipetteOptions(volRows=[],selected='AUTO'){let out=`<option value="NONE" ${selected==='NONE'?'selected':''}>N/A · directo del patrón</option><option value="AUTO" ${selected==='AUTO'?'selected':''}>🤖 IA óptima · combinar materiales</option>`;out+=uvPipetteRows(volRows).map(x=>`<option value="IDX:${x.index}" ${String(selected)===`IDX:${x.index}`?'selected':''}>${esc(x.v.material)} ${uvFmt(x.capacity,3)} mL · uV=${uvFmt(x.uV,6)}${x.adjustable?' · ajustable':''}</option>`).join('');return out}
