 const close=()=>document.getElementById('conductivityCalibrationModal')?.remove();$('closeConductivity').onclick=close;$('coCancel').onclick=close;
 const activate=step=>{document.querySelectorAll('#condTabs .tab-btn').forEach(b=>b.classList.toggle('active',b.dataset.cstep===String(step)));document.querySelectorAll('.cond-step').forEach(p=>p.classList.toggle('active',p.dataset.cpanel===String(step)));$('coSign').style.display=String(step)==='4'?'':'none';recalc()};document.querySelectorAll('#condTabs .tab-btn').forEach(b=>b.onclick=()=>activate(b.dataset.cstep));
 let uid=baseRows.length;
 const addPair=(r={})=>{const id=r.id||`c${++uid}`,row={id,nominal:r.nominal??'',certified:r.certified??'',standardCode:r.standardCode||'',lot:r.lot||'',expiry:r.expiry||'',standardUncertaintyInput:r.standardUncertaintyInput??'',manufacturer:r.manufacturer||'',readings:r.readings||Array(10).fill('')};$('coTraceRows').insertAdjacentHTML('beforeend',traceRow(row));$('coMeasureRows').insertAdjacentHTML('beforeend',measureRow(row));bindRows();recalc()};
 const syncLabels=()=>document.querySelectorAll('.co-trace').forEach(tr=>{const mr=document.querySelector(`.co-measure[data-rid="${CSS.escape(tr.dataset.rid)}"]`);if(mr)mr.querySelector('.co-level-label').innerHTML=`<b>${esc(tr.querySelector('.co-nom').value||'—')}</b>`});
