  const uThermRes=Number.isFinite(thermRes)?thermRes/(2*Math.sqrt(3)):NaN,uGrad=Number.isFinite(grad)?grad/Math.sqrt(3):NaN,uCombinedT=[thermU,uThermRes,uGrad].every(Number.isFinite)?Math.sqrt(thermU**2+uThermRes**2+uGrad**2):NaN,uAlpha=Number.isFinite(alphaTol)?alphaTol/Math.sqrt(3):NaN,uRes=Number.isFinite(res)?res/(2*Math.sqrt(3)):NaN;
