function odMonthsBetween(a,b){const A=new Date(a+'T00:00:00'),B=new Date(b+'T00:00:00');if(!Number.isFinite(A.getTime())||!Number.isFinite(B.getTime()))return NaN;return Math.max(0.1,(B-A)/(1000*60*60*24*30.4375))}
function odComparableHistory(i,excludeId=''){
 const scope=String(i.scopeKey||'');return dossier.filter(d=>d.id!==excludeId&&d.equipmentId===i.equipment.id&&d.category==='CALIBRACION_INTERNA'&&String(d.scopeKey||d.generatedData?.scopeKey||'')===scope&&d.generatedData?.profile==='OD'&&Number.isFinite(Number(d.generatedData?.resultSummary?.error))).sort((a,b)=>String(b.generatedData?.date||b.issueDate||'').localeCompare(String(a.generatedData?.date||a.issueDate||'')));
}
