 const seed=Array.isArray(existing.rows)&&existing.rows.length?existing.rows:[
  {id:'ph4',label:'pH 4',nominal:4,certified:'',expandedU:'',k:2,code:'',lot:'',expiry:'',manufacturer:'',ph5:'',ph50:'',readings:Array(10).fill('')},
  {id:'ph7',label:'pH 7',nominal:7,certified:'',expandedU:'',k:2,code:'',lot:'',expiry:'',manufacturer:'',ph5:'',ph50:'',readings:Array(10).fill('')},
  {id:'ph10',label:'pH 10',nominal:10,certified:'',expandedU:'',k:2,code:'',lot:'',expiry:'',manufacturer:'',ph5:'',ph50:'',readings:Array(10).fill('')}
 ];
