 const traceRows=()=>[...document.querySelectorAll('.ph-trace')].map(tr=>{const id=tr.dataset.rid,mr=document.querySelector(`.ph-measure[data-rid="${id}"]`),tt=document.querySelector(`.ph-temp[data-rid="${id}"]`);return {id,label:mr?.querySelector('b')?.textContent||id,nominal:num(tr.querySelector('.ph-nom').value),certified:num(tr.querySelector('.ph-cert').value),expandedU:num(tr.querySelector('.ph-u').value),k:num(tr.querySelector('.ph-k').value)||2,code:tr.querySelector('.ph-code').value.trim(),lot:tr.querySelector('.ph-lot').value.trim(),expiry:tr.querySelector('.ph-exp').value,manufacturer:tr.querySelector('.ph-mfg').value.trim(),ph5:num(tt?.querySelector('.ph-ph5')?.value),ph50:num(tt?.querySelector('.ph-ph50')?.value),readings:Array.from({length:10},(_,k)=>num(mr?.querySelector(`.ph-r${k+1}`)?.value)).filter(Number.isFinite)}});
