function maintenanceIntervalAi(e,currentMonths,risk,result,activities,functional,controls){
 const cur=Math.max(1,Math.min(12,parseInt(currentMonths,10)||6));
 const r=String(risk||'MEDIO').toUpperCase();
 const bad=[...activities,...functional].filter(x=>['NO','REQUIERE_ACCION','NO_CONFORME'].includes(x.status)).length+controls.filter(x=>x.conformity==='NO_CONFORME').length;
 const prior=dossier.filter(d=>d.equipmentId===e.id&&d.category==='MANTENIMIENTO_INTERNO'&&d.generatedData).sort((a,b)=>String(b.issueDate||'').localeCompare(String(a.issueDate||''))).slice(0,4);
 const clean=prior.filter(d=>d.generatedData?.result==='OPERATIVO'&&!String(d.generatedData?.finding||'').trim()).length;
 let rec=cur,why=[];
 if(result==='FUERA DE SERVICIO'||result==='REQUIERE MANTENIMIENTO EXTERNO'||bad>=2){rec=Math.max(1,cur-2);why.push('resultado/hallazgos de alta atención')}
 else if(result==='OPERATIVO CON OBSERVACIONES'||bad===1){rec=Math.max(1,cur-1);why.push('existe observación o control que requiere seguimiento')}
 else if(result==='OPERATIVO'&&bad===0&&clean>=3){rec=Math.min(12,cur+2);why.push(`${clean} mantenimientos previos operativos sin hallazgos relevantes`)}
 else if(result==='OPERATIVO'&&bad===0&&clean>=2){rec=Math.min(12,cur+1);why.push(`${clean} mantenimientos previos operativos sin hallazgos relevantes`)}
 else {why.push(prior.length?'histórico todavía insuficiente para ampliar':'sin histórico suficiente para ampliar')}
 const cap=r==='ALTO'?6:(r==='MEDIO'?9:12);if(rec>cap){rec=cap;why.push(`criticidad ${r.toLowerCase()} limita la recomendación a ${cap} meses`)}
 if(r==='ALTO'&&bad>0)rec=Math.min(rec,3);
 return {months:Math.max(1,Math.min(12,rec)),reason:`Intervalo vigente: ${cur} meses. Riesgo: ${r}. ${why.join('; ')}. Recomendación basada en condición actual e histórico; requiere aprobación del responsable.`};
}
