function isCovPidMaintenanceEquipment(e){
 const k=normalizeKey([e?.name,e?.family,e?.technical?.brand,e?.technical?.model,e?.intendedUse].filter(Boolean).join(' '));
 return ['medidor de cov','medidor de covs','detector de cov','detector cov','mini rae','minirae','pgm-7320','pgm 7320','detector_cov_pid'].some(x=>k.includes(normalizeKey(x))) || (k.includes('cov') && k.includes('pid'));
}
