function matchMaintenanceTemplate(e){
 if(isCovPidMaintenanceEquipment(e))return maintenanceTemplates.find(t=>normalizeKey(t.family||'')===normalizeKey('DETECTOR_COV_PID')&&t.active!==false)||suggestedCovPidMaintenanceTemplate();
 const hay=normalizeKey([e.name,e.technical?.manufacturer,e.technical?.brand,e.technical?.model,e.intendedUse].join(' '));
 const isCaptadorMpEquipment=['captador de material particulado','captador de particulas','muestreador de material particulado','bgi pq200','pq200','pq 200'].some(k=>hay.includes(normalizeKey(k)));
 const isOdEquipment=['medidor de oxigeno disuelto','medidor de od','oximetro','sonda ldo','ldo101'].some(k=>hay.includes(normalizeKey(k))) && !hay.includes('multiparametro') && !hay.includes('conductividad');
 const isMultiEquipment=['multiparametro','hq40d','medidor de od','oxigeno disuelto'].some(k=>hay.includes(normalizeKey(k))) && (hay.includes('ph')||hay.includes('conductividad')||hay.includes('hq40d')||hay.includes('multiparametro'));
 const isThermoreactorEquipment=['termoreactor','termo reactor','drb200','drb 200','hach drb200'].some(k=>hay.includes(normalizeKey(k)));
 const isDistillerK350Equipment=['destilador','destillation unit','distillation unit','k-350','k350','ei-199'].some(k=>hay.includes(normalizeKey(k)));
 const isDigesterEquipment=!isDistillerK350Equipment&&!isThermoreactorEquipment&&['digestor','speeddigester','speed digester','buchi k-425','k-425','k425','kjeldahl'].some(k=>hay.includes(normalizeKey(k)));
 const isScrubberEquipment=['scrubber','buchi b-414','b-414','b414','lavador de gases','neutralizacion de vapores','neutralización de vapores','wet scrubber'].some(k=>hay.includes(normalizeKey(k)));
 const isVibrationEquipment=['vibrometro','vibrómetro','medidor de vibraciones','sv-106','sv106','ei-176','mano-brazo','cuerpo entero'].some(k=>hay.includes(normalizeKey(k)));
 const isChlorineEquipment=['medidor de cloro','cloro residual','pocket colorimeter','colorimetro de cloro','colorímetro de cloro','ei-172'].some(k=>hay.includes(normalizeKey(k)));
 const isDosimeterEquipmentMaint=['dosimetro','dosímetro','dosimetro de ruido','dosímetro de ruido','noise dosimeter','sv 104','sv104','ei-173'].some(k=>hay.includes(normalizeKey(k)));
 const isTgbhEquipmentMaint=['tgbh','wbgt','extech ht30','ht30','ei-198','ei/198','bulbo humedo','bulbo húmedo','temperatura de globo','estres termico','estrés térmico'].some(k=>hay.includes(normalizeKey(k)));
 const active=maintenanceTemplates.filter(t=>t.active!==false);let best=null,bestScore=0;
 for(const t of active){let score=0;const templateKey=normalizeKey([t.name,t.family,...(t.keywords||[])].join(' '));for(const k of (t.keywords||[])){const n=normalizeKey(k);if(n&&hay.includes(n))score+=Math.max(2,n.split(' ').length)}if(normalizeKey(t.family)&&hay.includes(normalizeKey(t.family)))score+=1;
  if(isCaptadorMpEquipment){if(templateKey.includes('captador_mp')||templateKey.includes('captador de material particulado')||templateKey.includes('pq200'))score+=150;else score-=100;}
  if(isOdEquipment){if(templateKey.includes('electroquimica / oxigeno disuelto'))score+=180;else if(templateKey.includes('multiparametro')||templateKey.includes('conductividad'))score-=100;}
  if(isMultiEquipment){if(['multiparametro','hq40d'].some(k=>templateKey.includes(normalizeKey(k))))score+=30;else if(templateKey.includes('conductividad')&&!templateKey.includes('multiparametro'))score-=10;}
  if(isThermoreactorEquipment){if(['termoreactor','drb200','drb 200','bloque termico'].some(k=>templateKey.includes(normalizeKey(k))))score+=80;else if(['digestor','speeddigester','k-425','kjeldahl','plato','plancha'].some(k=>templateKey.includes(normalizeKey(k))))score-=35;}
  if(isDistillerK350Equipment){if(templateKey.includes('destilacion / kjeldahl / buchi k-350')||templateKey.includes('destilador kjeldahl'))score+=250;else score-=150;}
  if(isDigesterEquipment){if(['digestor','speeddigester','k-425','kjeldahl'].some(k=>templateKey.includes(normalizeKey(k))))score+=35;else if(['calentamiento','plato','plancha'].some(k=>templateKey.includes(normalizeKey(k))))score-=12;}
  if(isScrubberEquipment){if(['scrubber','b-414','lavador de gases','neutralizacion'].some(k=>templateKey.includes(normalizeKey(k))))score+=45;else if(['digestor','destilador','conductividad','calentamiento'].some(k=>templateKey.includes(normalizeKey(k))))score-=20;}
  if(isDosimeterEquipmentMaint){if(['dosimetro','dosimetria','noise dosimeter','sv 104','sv104','ei-173'].some(k=>templateKey.includes(normalizeKey(k))))score+=100;else if(['sonometro','sonometria','medidor de nivel sonoro'].some(k=>templateKey.includes(normalizeKey(k))))score-=40;}
  if(isTgbhEquipmentMaint){if(['tgbh','wbgt','extech ht30','ei-198','temperatura / humedad / tgbh'].some(k=>templateKey.includes(normalizeKey(k))))score+=120;else if(['termohigrometro','termohigrómetro','sonometro','dosimetro'].some(k=>templateKey.includes(normalizeKey(k))))score-=35;}
  if(isVibrationEquipment){if(['vibrometro','vibrómetro','medidor de vibraciones','sv-106','ei-176','vibrometria'].some(k=>templateKey.includes(normalizeKey(k))))score+=90;else if(['sonometro','dosimetro','conductividad','uv-vis'].some(k=>templateKey.includes(normalizeKey(k))))score-=30;}
  if(isChlorineEquipment){if(['medidor de cloro','cloro residual','pocket colorimeter','colorimetria / cloro residual'].some(k=>templateKey.includes(normalizeKey(k))))score+=70;else if(['uv-vis','conductividad','sonometro','termoreactor','digestor'].some(k=>templateKey.includes(normalizeKey(k))))score-=25;}
  if(score>bestScore){best=t;bestScore=score}}
 return best;
}
function resolveMaintenanceTemplate(t,e){
 if(isCovPidMaintenanceEquipment(e)){const base=suggestedCovPidMaintenanceTemplate();const stored=maintenanceTemplates.find(x=>normalizeKey(x.family||'')===normalizeKey('DETECTOR_COV_PID'));return {...base,id:stored?.id||t?.id||''};}
 if(!t)return t;
 // Familia de destilacion: nunca heredar los controles del digestor K-425.
 const eqKey=normalizeKey([e?.code,e?.name,e?.technical?.model,e?.model].filter(Boolean).join(' '));
 const tKey=normalizeKey([t.name,t.family,...(t.keywords||[])].join(' '));
 const eqDistiller=eqKey.includes('ei-199')||eqKey.includes('ei/199')||eqKey.includes('destilador')||eqKey.includes('k-350')||eqKey.includes('k350');
 const tDistiller=tKey.includes('destilador')||tKey.includes('destilacion / kjeldahl / buchi k-350');
 if(eqDistiller && (tDistiller || tKey.includes('digestor') || tKey.includes('k-425') || tKey.includes('sonometro'))) {
  const baseDist=suggestedDistillerK350MaintenanceTemplate();
  return {...t,...baseDist,id:tDistiller?t.id:(maintenanceTemplates.find(x=>normalizeKey(x.name).includes('destilador kjeldahl'))?.id||t.id)};
 }

 const base=suggestedMaintenanceTemplate();
 const heating=normalizeKey([t.name,t.family,...(t.keywords||[]),e?.name].join(' '));
 const isHeating=['plato calentador','placa calefactora','plancha calentadora','hot plate','calentamiento'].some(k=>heating.includes(normalizeKey(k)));
 const refrigeratorBase=suggestedRefrigeratorMaintenanceTemplate();
 const conductivityBase=suggestedConductivityMaintenanceTemplate();
 const sonometerBase=suggestedSonometerMaintenanceTemplate();
 const dosimeterBase=suggestedDosimeterMaintenanceTemplate();
 const multiparameterBase=suggestedMultiparameterMaintenanceTemplate();
 const thermoreactorBase=suggestedThermoreactorCompactMaintenanceTemplate();
 const digesterBase=suggestedDigesterK425MaintenanceTemplate();
 const scrubberBase=suggestedScrubberMaintenanceTemplate();
 const vibrometerBase=suggestedVibrometerMaintenanceTemplate();
 const chlorineBase=suggestedChlorineMeterMaintenanceTemplate();
 const tgbhBase=suggestedTgbhMaintenanceTemplate();
 const isRefrigerator=['refrigerador','refrigeradora','nevera','refrigerator','fridge','refrigeracion'].some(k=>heating.includes(normalizeKey(k)));
 const isDosimeter=['dosimetro','dosímetro','dosimetro de ruido','dosímetro de ruido','noise dosimeter','dosimetria','sv 104','sv104','ei-173'].some(k=>heating.includes(normalizeKey(k)));
 const isSonometer=!isDosimeter&&['sonometro','sonómetro','medidor de nivel sonoro','sound level meter','sonometria'].some(k=>heating.includes(normalizeKey(k)));
 const isMultiparameter=['multiparametro','multiparámetro','hq40d','medidor multiparametro','medidor multiparámetro'].some(k=>heating.includes(normalizeKey(k)));
 const isThermoreactor=['termoreactor','termo reactor','drb200','drb 200','hach drb200'].some(k=>heating.includes(normalizeKey(k)));
 const isDigester=!isThermoreactor&&['digestor','speeddigester','speed digester','buchi k-425','k-425','k425','kjeldahl'].some(k=>heating.includes(normalizeKey(k)));
 const isScrubber=['scrubber','buchi b-414','b-414','b414','lavador de gases','neutralizacion de vapores','neutralización de vapores','wet scrubber'].some(k=>heating.includes(normalizeKey(k)));
 const isVibration=['vibrometro','vibrómetro','medidor de vibraciones','sv-106','sv106','ei-176','mano-brazo','cuerpo entero'].some(k=>heating.includes(normalizeKey(k)));
 const isChlorine=['medidor de cloro','cloro residual','pocket colorimeter','colorimetro de cloro','colorímetro de cloro','ei-172'].some(k=>heating.includes(normalizeKey(k)));
 const isTgbh=['tgbh','wbgt','extech ht30','ht30','ei-198','ei/198','bulbo humedo','bulbo húmedo','temperatura de globo','estres termico','estrés térmico'].some(k=>heating.includes(normalizeKey(k)));
 const isConductivity=!isMultiparameter&&['conductimetro','conductímetro','medidor de conductividad','conductivity meter','conductividad','seven easy'].some(k=>heating.includes(normalizeKey(k)));
 const fallback=isTgbh?tgbhBase:(isDosimeter?dosimeterBase:(isChlorine?chlorineBase:(isThermoreactor?thermoreactorBase:(isScrubber?scrubberBase:(isDigester?digesterBase:(isMultiparameter?multiparameterBase:(isSonometer?sonometerBase:(isConductivity?conductivityBase:(isRefrigerator?refrigeratorBase:base)))))))));
 const appliesFallback=isTgbh||isHeating||isRefrigerator||isConductivity||isDosimeter||isSonometer||isMultiparameter||isThermoreactor||isDigester||isScrubber||isChlorine;
 const compactThermoreactor=isThermoreactor && (String(t.documentVersion||'')!=='09'||t.compactLegacy!==true);
 const compactScrubber=isScrubber && String(t.documentVersion||'')!=='07';
 const upgradedDigester=isDigester && String(t.documentVersion||'')!=='08';
 const upgradedChlorine=isChlorine && (String(t.documentVersion||'')!=='10'||t.chlorineSmart!==true);
 const upgradedDosimeter=isDosimeter && (String(t.documentVersion||'')!=='11'||t.dosimeterSmart!==true);
 const upgradedTgbh=isTgbh && (String(t.documentVersion||'')!=='14'||t.tgbhSmart!==true);
 return {
  ...t,
  documentCode:t.documentCode||'PSI-PG0416',
  documentVersion:upgradedTgbh?'14':(upgradedDosimeter?'11':(upgradedChlorine?'10':(compactThermoreactor?'09':(upgradedDigester?'08':(compactScrubber?'07':(t.documentVersion||'02')))))),
  tgbhSmart:upgradedTgbh?true:(t.tgbhSmart===true),
  dosimeterSmart:upgradedDosimeter?true:(t.dosimeterSmart===true),
  chlorineSmart:upgradedChlorine?true:(t.chlorineSmart===true),
  compactLegacy:compactThermoreactor?true:(t.compactLegacy===true),
  objectiveHint:upgradedTgbh?tgbhBase.objectiveHint:(upgradedDosimeter?dosimeterBase.objectiveHint:(upgradedChlorine?chlorineBase.objectiveHint:(compactThermoreactor?thermoreactorBase.objectiveHint:(upgradedDigester?digesterBase.objectiveHint:(compactScrubber?scrubberBase.objectiveHint:(t.objectiveHint||(appliesFallback?fallback.objectiveHint:''))))))),
  materials:upgradedTgbh?tgbhBase.materials:(upgradedDosimeter?dosimeterBase.materials:(upgradedChlorine?chlorineBase.materials:(compactThermoreactor?[]:(upgradedDigester?digesterBase.materials:(compactScrubber?scrubberBase.materials:(t.materials?.length?t.materials:(appliesFallback?fallback.materials:[]))))))),
  activities:upgradedTgbh?tgbhBase.activities:(upgradedDosimeter?dosimeterBase.activities:(upgradedChlorine?chlorineBase.activities:(compactThermoreactor?thermoreactorBase.activities:(upgradedDigester?digesterBase.activities:(compactScrubber?scrubberBase.activities:(t.activities?.length?t.activities:(t.items?.length?t.items.map(x=>({task:x.task,required:x.required!==false})):(appliesFallback?fallback.activities:[])))))))),
  functionalChecks:upgradedTgbh?tgbhBase.functionalChecks:(upgradedDosimeter?dosimeterBase.functionalChecks:(upgradedChlorine?chlorineBase.functionalChecks:(compactThermoreactor?thermoreactorBase.functionalChecks:(upgradedDigester?digesterBase.functionalChecks:(compactScrubber?scrubberBase.functionalChecks:(t.functionalChecks?.length?t.functionalChecks:(appliesFallback?fallback.functionalChecks:[]))))))),
  controlChecks:upgradedTgbh?tgbhBase.controlChecks:(upgradedDosimeter?dosimeterBase.controlChecks:(upgradedChlorine?chlorineBase.controlChecks:(compactThermoreactor?thermoreactorBase.controlChecks:(upgradedDigester?digesterBase.controlChecks:(compactScrubber?scrubberBase.controlChecks:(t.controlChecks?.length?t.controlChecks:(appliesFallback?fallback.controlChecks:[]))))))),
  photoPolicy:upgradedTgbh?tgbhBase.photoPolicy:(upgradedDosimeter?dosimeterBase.photoPolicy:(upgradedChlorine?chlorineBase.photoPolicy:(compactThermoreactor?thermoreactorBase.photoPolicy:(t.photoPolicy||(appliesFallback?fallback.photoPolicy:base.photoPolicy)))))
 };
}
function maintenanceCode(e,date){
 const year=String(date||new Date().toISOString().slice(0,10)).slice(2,4);
 const fullYear=String(date||new Date().toISOString().slice(0,10)).slice(0,4);
 const count=dossier.filter(d=>d.equipmentId===e.id&&d.category==='MANTENIMIENTO_INTERNO'&&String(d.issueDate||'').startsWith(fullYear)).length+1;
 return `IM-${String(e.code||'EQ').toUpperCase()}-${year}-${String(count).padStart(3,'0')}`;
}
function applySmartMaintenanceControls(template){
 if(!template?.chlorineSmart)return;
 const rows=[...document.querySelectorAll('.miControlRow')];
 let allSpecific=true,seenSpecific=0;
 for(const r of rows){
  const rule=r.dataset.smartRule||''; const input=r.querySelector('.miControlResult'); const sel=r.querySelector('.miControlConformity');
  if(!rule||rule==='CHLORINE_GENERAL')continue;
  const nums=(String(input?.value||'').replace(/,/g,'.').match(/-?\d+(?:\.\d+)?/g)||[]).map(Number).filter(Number.isFinite);
  let ok=null;
  if(rule==='CHLORINE_BLANK'&&nums.length)ok=Math.abs(nums[0])<=0.02;
  if(rule==='CHLORINE_STABILITY'&&nums.length)ok=Math.abs(nums[0])<=0.01;
  if(rule==='CHLORINE_DPD'&&nums.length>=2&&nums[0]!==0){const dev=Math.abs((nums[1]-nums[0])/nums[0])*100;ok=dev<=5; input.title=`Desviación calculada: ${dev.toFixed(2)} %`}
  if(ok!==null){sel.value=ok?'CONFORME':'NO_CONFORME';seenSpecific++;if(!ok)allSpecific=false}else if(input?.value.trim()){allSpecific=false}
 }
 const general=rows.find(r=>r.dataset.smartRule==='CHLORINE_GENERAL');
 if(general&&seenSpecific>=3){general.querySelector('.miControlResult').value=allSpecific?'Todos los controles conformes':'Existe al menos un control no conforme';general.querySelector('.miControlConformity').value=allSpecific?'CONFORME':'NO_CONFORME'}
}
function maintenanceAiDecision(activities,functional,controls){
 const all=[...activities,...functional].map(x=>x.status).filter(Boolean);
 const controlStates=controls.map(x=>x.conformity).filter(Boolean);
 if(!all.length&&!controlStates.length)return {decision:'',reason:'Complete las actividades y verificaciones aplicables.'};
 if(all.includes('NO')||all.includes('REQUIERE_ACCION')||all.includes('NO_CONFORME')||controlStates.includes('NO_CONFORME'))return {decision:'OPERATIVO CON OBSERVACIONES',reason:'Se detectó al menos una actividad o control que requiere atención. Revise el hallazgo antes de confirmar el estado final.'};
 const pending=[...activities,...functional].some(x=>x.required&&!x.status)||controls.some(x=>x.required===true&&(!x.result||!x.conformity));
 if(pending)return {decision:'',reason:'Existen actividades o verificaciones obligatorias pendientes.'};
 return {decision:'OPERATIVO',reason:'Todas las actividades y verificaciones aplicables fueron registradas como conformes.'};
}
function maintenanceObjective(e,t,kind){
 const base=t?.objectiveHint||'limpieza, inspección, revisión funcional y comprobación de condiciones de operación';
 return `${kind==='CORRECTIVO'?'Realizar mantenimiento correctivo':'Realizar mantenimiento preventivo'} del equipo ${e.name} (${e.code}) mediante ${base.toLowerCase()}, con el fin de conservar condiciones seguras de operación, desempeño adecuado y trazabilidad del equipo.`;
}
function maintenanceConclusion(e,data){
 const bad=[...data.activities,...data.functionalChecks].filter(x=>['NO','REQUIERE_ACCION','NO_CONFORME'].includes(x.status));
 const badCtrl=data.controlChecks.filter(x=>x.conformity==='NO_CONFORME');
 if(data.result==='OPERATIVO'&&!bad.length&&!badCtrl.length)return `El equipo ${e.code} (${e.name}) completó el mantenimiento ${data.kind.toLowerCase()} y las verificaciones post-mantenimiento registradas resultaron conformes. El equipo queda operativo para continuar su uso previsto. Se recomienda mantener el seguimiento conforme a la frecuencia programada.`;
 if(data.result==='FUERA DE SERVICIO')return `El equipo ${e.code} (${e.name}) presenta condiciones que impiden su uso. Se deja fuera de servicio hasta ejecutar y documentar las acciones necesarias para su retorno.`;
 return `El equipo ${e.code} (${e.name}) completó el mantenimiento ${data.kind.toLowerCase()} con observaciones o acciones pendientes. Revise los hallazgos registrados, defina seguimiento y confirme las condiciones de uso antes de continuar la operación normal.`;
}
