 addMtMaterial.onclick=()=>{mtMaterials.insertAdjacentHTML('beforeend',materialRow({}));bind()};addMtActivity.onclick=()=>{mtActivities.insertAdjacentHTML('beforeend',activityTemplateRow({}));bind()};addMtFunctional.onclick=()=>{mtFunctional.insertAdjacentHTML('beforeend',functionalTemplateRow({}));bind()};addMtControl.onclick=()=>{mtControls.insertAdjacentHTML('beforeend',controlTemplateRow({}));bind()};
 saveMaintTemplate.onclick=async()=>{const materials=[...document.querySelectorAll('.mtMaterialRow')].map(r=>({material:r.querySelector('.mtMaterial').value.trim(),use:r.querySelector('.mtUse').value.trim()})).filter(x=>x.material);const activities=[...document.querySelectorAll('.mtActivityRow')].map(r=>({task:r.querySelector('.mtActivity').value.trim(),required:r.querySelector('.mtReq').checked})).filter(x=>x.task);const functionalChecks=[...document.querySelectorAll('.mtFunctionalRow')].map(r=>({check:r.querySelector('.mtCheck').value.trim(),required:r.querySelector('.mtReq').checked})).filter(x=>x.check);const controlChecks=[...document.querySelectorAll('.mtControlRow')].map(r=>({parameter:r.querySelector('.mtParameter').value.trim(),criterion:r.querySelector('.mtControlCriterion').value.trim(),required:!!r.querySelector('.mtControlReq')?.checked})).filter(x=>x.parameter);const data={name:mtName.value.trim(),family:mtFamily.value.trim(),keywords:mtKeywords.value.split(',').map(x=>x.trim()).filter(Boolean),description:'Formato técnico de mantenimiento interno',documentCode:mtDocCode.value.trim()||'PSI-PG0416',documentVersion:mtDocVersion.value.trim()||'02',objectiveHint:mtObjectiveHint.value.trim(),materials,activities,functionalChecks,controlChecks,items:activities.map((x,n)=>({id:`item_${n+1}`,section:'Actividades realizadas',task:x.task,required:x.required})),photoPolicy:{enabled:false,beforeMax:2,afterMax:2},active:true};try{saveMaintTemplate.disabled=true;mtMsg.textContent='Guardando formato…';if(edit?.id)await updateMaintenanceTemplate(edit.id,data,currentUser);else await createMaintenanceTemplate(data,currentUser);close();currentPage='maintenanceInternal';renderApp()}catch(err){mtMsg.textContent=err.message||String(err);mtMsg.classList.add('bad');saveMaintTemplate.disabled=false}};
