async function migrateLegacySignatureBaselines(){
 if(!currentUser||!equipment.length||!dossier.length)return;
 for(const e of equipment){
  const ds=e.documentStatus||{};
  if(!ds.latestSignedRevision||ds.latestSignedSnapshotHash)continue;
  const signed=dossier.filter(d=>d.equipmentId===e.id&&d.category==='FICHA_MAESTRA'&&d.signature?.signed&&isArchivedDoc(d)).sort((a,b)=>(parseInt(b.revision)||0)-(parseInt(a.revision)||0))[0];
  if(!signed)continue;

  // La línea base DEBE ser la huella de la revisión realmente firmada.
  // Nunca usar silenciosamente la ficha viva actual como baseline, porque eso
  // haría que una edición posterior pareciera todavía firmada.
  const signedSnapshotHash=String(signed.equipmentSnapshotHash||signed.signature?.snapshotHash||'').trim();
  const currentSnapshotHash=await hashEquipmentSnapshot(e);
  const baseline=signedSnapshotHash || ds.currentSnapshotHash || currentSnapshotHash;
  const differs=!!baseline && currentSnapshotHash!==baseline;
  const lastNum=parseInt(String(signed.revision||ds.latestSignedRevision||'0').replace(/\D/g,''),10)||0;
  const next=String(lastNum+1).padStart(2,'0');

  await updateEquipmentDocumentStatus(e.id,{
    ...ds,
    latestSignedRevision:signed.revision||ds.latestSignedRevision,
    latestSignedDocumentId:signed.id,
    latestSignedSnapshotHash:baseline,
    currentSnapshotHash,
    workingRevision:differs?next:(signed.revision||ds.latestSignedRevision),
    pendingRevision:differs?next:'',
    workingState:differs?'BORRADOR_PENDIENTE_FIRMA':'VIGENTE_FIRMADA',
    signatureState:differs?'PENDIENTE_NUEVA_FIRMA':'VIGENTE',
    pendingChangeSections:differs?['Cambios detectados respecto a la revisión firmada']:[],
    baselineMigratedAt:new Date().toISOString()
  },currentUser);
 }
}


function historyDateValue(v){
 if(!v)return '';
 if(typeof v==='string'){
  const raw=v.trim();
  const iso=raw.match(/(\d{4}-\d{2}-\d{2})(?!.*\d{4}-\d{2}-\d{2})/);
  if(iso)return iso[1];
  const lat=raw.match(/(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
  if(lat)return `${lat[3]}-${String(lat[2]).padStart(2,'0')}-${String(lat[1]).padStart(2,'0')}`;
  return raw.slice(0,10);
 }
 if(v?.toDate)return v.toDate().toISOString().slice(0,10);
 if(v?.seconds)return new Date(v.seconds*1000).toISOString().slice(0,10);
 return '';
}
function historyTs(v){
 if(!v)return 0;
 if(typeof v==='string')return new Date(v+'T12:00:00').getTime()||0;
 if(v?.toMillis)return v.toMillis();
 if(v?.seconds)return v.seconds*1000;
 return 0;
}
